-- Generated by tools/build_action_data.py; do not edit.
return {["modules/era/lua/actions/abilities/pets/automaton/attachments.lua"]={["Path"]="modules/era/lua/actions/abilities/pets/automaton/attachments.lua",["SHA256"]="c5fe97fddd609dd7e6f13ebc3c772058d6d0ac2430de5b972b75beb6877060dd",["Text"]="-----------------------------------\n-- Attachment module\n-- Recreates attachment effects in the WoTG Era.\n-----------------------------------\nrequire('modules/module_utils')\nrequire('scripts/globals/automaton')\n-----------------------------------\n\nlocal m = Module:new('attachments', xi.pre(xi.expansion.ABYSSEA))\n\nm:addOverride('xi.server.onServerStart', function()\n    super()\n\n    -- Reduces Enmity boost from Strobe                                  : https://wiki.ffo.jp/html/8610.html\n    -- Reduces Store TP from Inhibitor                                   : https://wiki.ffo.jp/html/8625.html\n    -- Changes Armor Plate and Armor Plate II to Defense instead of PDT  : https://wiki.ffo.jp/html/9070.html\n    -- Adds a Ranged Attack Penalty to Drum Magazine.                    : https://wiki.ffo.jp/html/8882.html\n    -- Changes Turbo Charger Haste to Gear Haste instead of Magic        : https://wiki.ffo.jp/html/8627.html\n    -- Adds Burden to Tactical Processor                                 : https://wiki.ffo.jp/html/13527.html\n    -- Reduces scaling from Volt Gun                                     : https://wiki.ffo.jp/html/8752.html\n    -- Reduces Burden Decay From Heatsink                                : https://wiki.ffo.jp/html/8629.html\n    -- Reduces the potency of Steam Jackets Damage Reduction             : https://wiki.ffo.jp/html/15352.html\n    -- Changes Mana Booster from Fast Cast, to global cooldown reduction : https://wiki.ffo.jp/html/8622.html\n    xi.automaton.attachmentModifiers['strobe'            ] = { { modifier = xi.mod.ENMITY,                      values = {   5,   15,   25,   40 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['inhibitor'         ] = { { modifier = xi.mod.STORETP,                     values = {   5,   10,   15,   20 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['armor_plate'       ] = { { modifier = xi.mod.DEFP,                        values = {  10,   15,   20,   25 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['armor_plate_ii'    ] = { { modifier = xi.mod.DEFP,                        values = {  20,   25,   30,   35 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['drum_magazine'     ] = { { modifier = xi.mod.AUTO_RANGED_DELAY,           values = {   2,    4,    6,    8 }, opticFiber = false },\n                                                                { modifier = xi.mod.RACC,                        values = { -15,  -30,  -50,  -75 }, opticFiber = false }, }\n    xi.automaton.attachmentModifiers['flame_holder'      ] = { { modifier = xi.mod.WEAPONSKILL_DAMAGE_BASE,     values = {   0,  125,  150,  175 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['ice_maker'         ] = { { modifier = xi.mod.AUTO_MAB_COEFFICIENT,        values = {   0,   20,   40,   60 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['turbo_charger'     ] = { { modifier = xi.mod.HASTE_GEAR,                  values = { 500, 1500, 2000, 2500 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['tactical_processor'] = { { modifier = xi.mod.AUTO_DECISION_DELAY,         values = {  50,   70,   85,  115 }, opticFiber = false },\n                                                                { modifier = xi.mod.OVERLOAD_THRESH,             values = {  -5,   -5,   -5,   -5 }, opticFiber = false }, }\n    xi.automaton.attachmentModifiers['volt_gun'          ] = { { modifier = xi.mod.VOLT_GUN_POTENCY,            values = {   0,    0,    0,    0 }, opticFiber = false }, }\n    xi.automaton.attachmentModifiers['heatsink'          ] = { { modifier = xi.mod.BURDEN_DECAY,                values = {   1,    1,    1,    1 }, opticFiber = false }, }\n    xi.automaton.attachmentModifiers['steam_jacket'      ] = { { modifier = xi.mod.AUTO_STEAM_JACKET_REDUCTION, values = {  25,   35,   40,   60 }, opticFiber = true  }, }\n    xi.automaton.attachmentModifiers['mana_booster'      ] = { { modifier = xi.mod.AUTO_MAGIC_COOLDOWN,         values = {  -2,   -4,   -6,   -8 }, opticFiber = false }, }\n\n    -- Reduces potency of Auto Repair Kit II and removed level based scaling from Mana Tank : https://wiki.ffo.jp/html/19739.html\n    xi.automaton.repairKit.data['auto-repair_kit_ii' ] = { id = 196, hpBoost = 2, regenBase   = { 0, 2, 3, 4 }, regenMultiplier   = { 0, 0.4, 0.6, 0.8 } }\n    xi.automaton.manaTank.data ['mana_tank'          ] = { id = 225, mpBoost = 1, refreshBase = { 0, 1, 2, 3 }, refreshMultiplier = { 0, 0.0, 0.0, 0.0 } }\n    xi.automaton.manaTank.data ['mana_tank_ii'       ] = { id = 228, mpBoost = 2, refreshBase = { 0, 2, 3, 4 }, refreshMultiplier = { 0, 0.0, 0.0, 0.0 } }\nend)\n\n-----------------------------------\n-- Flame Holder - Reduces Flame Holder Scaling, and consumes all Fire Maneuvers on weaponskill execution. https://wiki.ffo.jp/html/11183.html\n-----------------------------------\nlocal validFlameHolderSkills = set\n{\n    xi.mobSkill.ARCUBALLISTA_AUTOMATON,\n    xi.mobSkill.ARMOR_PIERCER_AUTOMATON,\n    xi.mobSkill.ARMOR_SHATTERER_AUTOMATON,\n    xi.mobSkill.BONE_CRUSHER_AUTOMATON,\n    xi.mobSkill.CANNIBAL_BLADE_AUTOMATON,\n    xi.mobSkill.CHIMERA_RIPPER_AUTOMATON,\n    xi.mobSkill.DAZE_AUTOMATON,\n    xi.mobSkill.KNOCKOUT_AUTOMATON,\n    xi.mobSkill.MAGIC_MORTAR_AUTOMATON,\n    xi.mobSkill.SLAPSTICK_AUTOMATON,\n    xi.mobSkill.STRING_CLIPPER_AUTOMATON,\n    xi.mobSkill.STRING_SHREDDER_AUTOMATON,\n}\n\nm:addOverride('xi.actions.abilities.pets.attachments.flame_holder.onEquip', function(pet, attachment)\n    pet:addListener('WEAPONSKILL_STATE_EXIT', 'AUTO_FLAME_HOLDER_END', function(automaton, skillId, wasExecuted)\n        if not validFlameHolderSkills[skillId] then\n            return\n        end\n\n        if not wasExecuted then\n            return\n        end\n\n        local master = automaton:getMaster()\n\n        if not master then\n            return\n        end\n\n        -- Consume all Fire Maneuvers on weaponskill execution.\n        local fireManeuvers = master:countEffect(xi.effect.FIRE_MANEUVER)\n\n        for i = 1, fireManeuvers do\n            master:delStatusEffectSilent(xi.effect.FIRE_MANEUVER)\n        end\n\n        master:updateAttachments()\n    end)\n\n    xi.automaton.onAttachmentEquip(pet, attachment)\nend)\n\nm:addOverride('xi.actions.abilities.pets.attachments.flame_holder.onUnequip', function(pet, attachment)\n    xi.automaton.onAttachmentUnequip(pet, attachment)\n    pet:removeListener('AUTO_FLAME_HOLDER_END')\nend)\n\n-----------------------------------\n-- Ice Maker - Reduces Magic Attack Bonus from Ice Maker, and consumes all Ice Maneuvers on magic attack execution. https://wiki.ffo.jp/html/11198.html\n-----------------------------------\nlocal validIceMakerSpells = set\n{\n    xi.magic.spell.FIRE,\n    xi.magic.spell.FIRE_II,\n    xi.magic.spell.FIRE_III,\n    xi.magic.spell.FIRE_IV,\n    xi.magic.spell.FIRE_V,\n    xi.magic.spell.BLIZZARD,\n    xi.magic.spell.BLIZZARD_II,\n    xi.magic.spell.BLIZZARD_III,\n    xi.magic.spell.BLIZZARD_IV,\n    xi.magic.spell.BLIZZARD_V,\n    xi.magic.spell.AERO,\n    xi.magic.spell.AERO_II,\n    xi.magic.spell.AERO_III,\n    xi.magic.spell.AERO_IV,\n    xi.magic.spell.AERO_V,\n    xi.magic.spell.STONE,\n    xi.magic.spell.STONE_II,\n    xi.magic.spell.STONE_III,\n    xi.magic.spell.STONE_IV,\n    xi.magic.spell.STONE_V,\n    xi.magic.spell.THUNDER,\n    xi.magic.spell.THUNDER_II,\n    xi.magic.spell.THUNDER_III,\n    xi.magic.spell.THUNDER_IV,\n    xi.magic.spell.THUNDER_V,\n    xi.magic.spell.WATER,\n    xi.magic.spell.WATER_II,\n    xi.magic.spell.WATER_III,\n    xi.magic.spell.WATER_IV,\n    xi.magic.spell.WATER_V,\n}\n\nm:addOverride('xi.actions.abilities.pets.attachments.ice_maker.onEquip', function(pet, attachment)\n    pet:addListener('MAGIC_USE', 'AUTO_ICE_MAKER_USE', function(automaton, target, spell, action)\n        if not validIceMakerSpells[spell:getID()] then\n            return\n        end\n\n        local master = automaton:getMaster()\n\n        if not master then\n            return\n        end\n\n        local iceManeuvers = master:countEffect(xi.effect.ICE_MANEUVER)\n\n        for i = 1, iceManeuvers do\n            master:delStatusEffectSilent(xi.effect.ICE_MANEUVER)\n        end\n\n        master:updateAttachments()\n    end)\n\n    xi.automaton.onAttachmentEquip(pet, attachment)\nend)\n\nm:addOverride('xi.actions.abilities.pets.attachments.ice_maker.onUnequip', function(pet, attachment)\n    xi.automaton.onAttachmentUnequip(pet, attachment)\n    pet:removeListener('AUTO_ICE_MAKER_USE')\nend)\n\n-----------------------------------\n-- Replicator - Reduces amount of absorbs granted by Replicator, and changes them to Blink from Utsusemi. Also consumes Wind Maneuvers. https://wiki.ffo.jp/html/12225.html\n-----------------------------------\nlocal shadowTable =\n{\n    [1] = 2,\n    [2] = 3,\n    [3] = 4,\n}\n\nm:addOverride('xi.actions.abilities.pets.automaton.replicator.onAutomatonAbilityCheck', function(target, automaton, skill)\n    return 0\nend)\n\nm:addOverride('xi.actions.abilities.pets.automaton.replicator.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local windManeuvers = xi.automaton.getManeuverCount(master, master:countEffect(xi.effect.WIND_MANEUVER))\n    local shadows       = shadowTable[windManeuvers]\n\n    automaton:addRecast(xi.recast.ABILITY, skill:getID(), 60)\n\n    for i = 1, windManeuvers do\n        master:delStatusEffectSilent(xi.effect.WIND_MANEUVER)\n    end\n\n    master:updateAttachments()\n\n    if\n        shadows and\n        target:addStatusEffect(xi.effect.BLINK, { power = shadows, duration = 300, origin = automaton })\n    then\n        skill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT)\n    else\n        skill:setMsg(xi.msg.basic.SKILL_NO_EFFECT)\n    end\n\n    return xi.effect.BLINK\nend)\n\n-----------------------------------\n-- Shock Absorber - Reduces the potency of the stoneskin effect and removes scaling. https://wiki.ffo.jp/html/12927.html\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.automaton.shock_absorber.onAutomatonAbilityCheck', function(target, automaton, skill)\n    return 0\nend)\n\nm:addOverride('xi.actions.abilities.pets.automaton.shock_absorber.onAutomatonAbility', function(target, automaton, skill, master, action)\n    automaton:addRecast(xi.recast.ABILITY, skill:getID(), 180)\n\n    if target:addStatusEffect(xi.effect.STONESKIN, { power = 100, duration = 180, origin = automaton, tier = 4 }) then\n        skill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT)\n    else\n        skill:setMsg(xi.msg.basic.SKILL_NO_EFFECT)\n    end\n\n    return xi.effect.STONESKIN\nend)\n\n-----------------------------------\n-- Shield Bash - Removes gaurunteed hit chance while Hammermill is equipped. https://wiki.ffo.jp/html/12156.html\n-----------------------------------\nlocal shieldBashSlowTable =\n{\n    [1] = { tier = 4, duration = 30 },\n    [2] = { tier = 5, duration = 50 },\n    [3] = { tier = 6, duration = 70 },\n}\n\nlocal function applyHammermillSlow(automaton, target, skill, master)\n    local power = automaton:getMod(xi.mod.AUTO_SHIELD_BASH_SLOW) * 100\n    if power <= 0 then\n        return\n    end\n\n    local slowTier = shieldBashSlowTable[master and xi.automaton.getManeuverCount(master, master:countEffect(xi.effect.EARTH_MANEUVER)) or 0]\n\n    local params =\n    {\n        [1] = { effectId = xi.effect.SLOW, power = power, duration = slowTier.duration, tier = slowTier.tier },\n    }\n\n    xi.combat.action.executeMobskillStatusEffect(automaton, target, skill, params, { messageBypass = true })\nend\n\nm:addOverride('xi.actions.abilities.pets.automaton.shield_bash.onAutomatonAbilityCheck', function(target, automaton, skill)\n    return 0\nend)\n\n-----------------------------------\n-- Hammermill\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.automaton.shield_bash.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage     = automaton:getWeaponDmg()\n    params.numHits        = utils.clamp(1 + xi.automaton.getExtraHits(automaton, 1), 1, 8)\n    params.fTP            = { 1.0, 1.0, 1.0 }\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.shadowBehavior = params.numHits\n\n    local hammermillEquipped = automaton:hasAttachmentSet(xi.item.HAMMERMILL_ATTACHMENT)\n\n    if hammermillEquipped then\n        local shieldBashBonus = 1.0 + automaton:getMod(xi.mod.SHIELD_BASH) / 100\n\n        params.fTP =\n        {\n            params.fTP[1] * shieldBashBonus,\n            params.fTP[2] * shieldBashBonus,\n            params.fTP[3] * shieldBashBonus,\n        }\n    end\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(automaton, target, xi.effect.STUN, 1, 0, 6)\n\n        if hammermillEquipped then\n            applyHammermillSlow(automaton, target, skill, master)\n        end\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Analyzer - Caps the amount of skills that can be analyzed to 1. https://wiki.ffo.jp/html/10746.html\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.attachments.analyzer.onEquip', function(pet, attachment)\n    pet:setLocalVar('analyzedSkill1', 0)\n\n    pet:addListener('WEAPONSKILL_TAKE', 'ANALYZER_WEAPONSKILL_TAKE', function(mob, target, skill, tp, action)\n        local analyzerModifier = target:getMod(xi.mod.AUTO_ANALYZER)\n        local incomingSkill    = skill:getID()\n\n        if analyzerModifier <= 0 then\n            return\n        end\n\n        local analyzedSkill = target:getLocalVar('analyzedSkill1')\n\n        if incomingSkill == analyzedSkill then\n            return\n        end\n\n        if incomingSkill ~= analyzedSkill then\n            target:setLocalVar('analyzedSkill1', incomingSkill)\n        end\n    end)\n\n    xi.automaton.onAttachmentEquip(pet, attachment)\nend)\n\nm:addOverride('xi.actions.abilities.pets.attachments.analyzer.onUnequip', function(pet, attachment)\n    pet:setLocalVar('analyzedSkill1', 0)\n\n    pet:removeListener('ANALYZER_WEAPONSKILL_TAKE')\n\n    xi.automaton.onAttachmentUnequip(pet, attachment)\nend)\n\nm:addOverride('xi.actions.abilities.pets.attachments.analyzer.onManeuverGain', function(pet, attachment, maneuvers)\nend)\n\nm:addOverride('xi.actions.abilities.pets.attachments.analyzer.onManeuverLose', function(pet, attachment, maneuvers)\nend)\n\nm:addOverride('xi.actions.abilities.pets.attachments.analyzer.onUpdate', function(pet, attachment, maneuvers)\nend)\n\nm:addOverride('utils.handleAutomatonAutoAnalyzer', function(actor, skill, damage)\n    local analyzerModifier = actor:getMod(xi.mod.AUTO_ANALYZER)\n\n    if analyzerModifier <= 0 then\n        return damage\n    end\n\n    local automatonId = actor:getID()\n\n    if not automatonId then\n        return damage\n    end\n\n    local automatonMaster = actor:getMaster()\n\n    if not automatonMaster then\n        return damage\n    end\n\n    local incomingSkill = skill:getID()\n    local analyzedSkill = actor:getLocalVar('analyzedSkill1')\n\n    if incomingSkill == analyzedSkill then\n        local earthManeuvers  = xi.automaton.getManeuverCount(automatonMaster, automatonMaster:countEffect(xi.effect.EARTH_MANEUVER))\n        local damageReduction = 10 + 10 * earthManeuvers\n\n        return math.floor(damage * (100 - damageReduction) / 100)\n    end\n\n    return damage\nend)\n\n-----------------------------------\n-- Eraser - Changes Eraser to consume all Maneuvers on activation. https://wiki.ffo.jp/html/5365.html\n-----------------------------------\nlocal maneuvers =\n{\n    xi.effect.FIRE_MANEUVER,\n    xi.effect.ICE_MANEUVER,\n    xi.effect.WIND_MANEUVER,\n    xi.effect.EARTH_MANEUVER,\n    xi.effect.THUNDER_MANEUVER,\n    xi.effect.WATER_MANEUVER,\n    xi.effect.LIGHT_MANEUVER,\n    xi.effect.DARK_MANEUVER,\n}\n\nlocal function removeAllManeuvers(master)\n    -- Era Eraser consumes all active maneuvers, not just Light Maneuvers.\n    for _, maneuverId in ipairs(maneuvers) do\n        for _ = 1, master:countEffect(maneuverId) do\n            master:delStatusEffectSilent(maneuverId)\n        end\n    end\nend\n\nlocal removables =\n{\n    -- Songs\n    xi.effect.ELEGY,\n    xi.effect.REQUIEM,\n    xi.effect.THRENODY,\n\n    -- Enfeebling\n    xi.effect.BLINDNESS,\n    xi.effect.PARALYSIS,\n    xi.effect.SILENCE,\n    xi.effect.POISON,\n    xi.effect.CURSE_I,\n    xi.effect.CURSE_II,\n    xi.effect.DISEASE,\n    xi.effect.PLAGUE,\n    xi.effect.WEIGHT,\n    xi.effect.BIND,\n    xi.effect.ADDLE,\n    xi.effect.SLOW,\n    xi.effect.PETRIFICATION,\n\n    -- DoTs\n    xi.effect.BIO,\n    xi.effect.DIA,\n    xi.effect.BURN,\n    xi.effect.FROST,\n    xi.effect.CHOKE,\n    xi.effect.RASP,\n    xi.effect.SHOCK,\n    xi.effect.DROWN,\n\n    -- Main Stat Downs\n    xi.effect.STR_DOWN,\n    xi.effect.DEX_DOWN,\n    xi.effect.VIT_DOWN,\n    xi.effect.AGI_DOWN,\n    xi.effect.INT_DOWN,\n    xi.effect.MND_DOWN,\n    xi.effect.CHR_DOWN,\n\n    -- Combat Stat Downs\n    xi.effect.ACCURACY_DOWN,\n    xi.effect.ATTACK_DOWN,\n    xi.effect.EVASION_DOWN,\n    xi.effect.DEFENSE_DOWN,\n\n    -- Magic Stat Downs\n    xi.effect.MAGIC_ACC_DOWN,\n    xi.effect.MAGIC_ATK_DOWN,\n    xi.effect.MAGIC_EVASION_DOWN,\n    xi.effect.MAGIC_DEF_DOWN,\n\n    -- HP/MP/TP Stat Downs\n    xi.effect.MAX_TP_DOWN,\n    xi.effect.MAX_MP_DOWN,\n    xi.effect.MAX_HP_DOWN,\n}\n\nm:addOverride('xi.actions.abilities.pets.automaton.eraser.onAutomatonAbilityCheck', function(target, automaton, skill)\n    return 0\nend)\n\nm:addOverride('xi.actions.abilities.pets.automaton.eraser.onAutomatonAbility', function(target, automaton, skill, master, action)\n    automaton:addRecast(xi.recast.ABILITY, skill:getID(), 30)\n\n    local lightManeuvers = xi.automaton.getManeuverCount(master, master:countEffect(xi.effect.LIGHT_MANEUVER))\n    local effectsRemoved = 0\n\n    for _, effectId in ipairs(removables) do\n        if target:hasStatusEffect(effectId) then\n            target:delStatusEffectSilent(effectId)\n            effectsRemoved = effectsRemoved + 1\n\n            if effectsRemoved >= lightManeuvers then\n                break\n            end\n        end\n    end\n\n    removeAllManeuvers(master)\n    master:updateAttachments()\n\n    if effectsRemoved > 0 then\n        skill:setMsg(xi.msg.basic.DISAPPEAR_NUM)\n    else\n        skill:setMsg(xi.msg.basic.USES)\n    end\n\n    return effectsRemoved\nend)\n\n-----------------------------------\n-- Economizer - Changes Economizer to consume all Dark Maneuvers on activation. : https://wiki.ffo.jp/html/10435.html\n-----------------------------------\nlocal activationThresholds =\n{\n    [0] = 30,\n    [1] = 40,\n    [2] = 50,\n    [3] = 60,\n}\n\nm:addOverride('xi.actions.abilities.pets.attachments.economizer.onEquip', function(pet)\n    pet:addListener('AUTOMATON_ATTACHMENT_CHECK', 'ATTACHMENT_ECONOMIZER', function(automaton, target)\n        -- If Economizer is still on cooldown, do nothing.\n        if automaton:hasRecast(xi.recast.ABILITY, xi.mobSkill.ECONOMIZER_AUTOMATON) then\n            return\n        end\n\n        local master = automaton:getMaster()\n\n        if not master then\n            return\n        end\n\n        local darkManeuvers = master:countEffect(xi.effect.DARK_MANEUVER)\n\n        if darkManeuvers == 0 then\n            return\n        end\n\n        local maxMP = automaton:getMaxMP()\n\n        -- If this automaton has no MP, do nothing.\n        if maxMP == 0 then\n            return\n        end\n\n        local mpPercent = automaton:getMPP()\n        local mpThreshold = activationThresholds[darkManeuvers] or 30\n\n        -- If the automaton's MP is above the threshold, do nothing.\n        if mpPercent > mpThreshold then\n            return\n        end\n\n        automaton:useMobAbility(xi.mobSkill.ECONOMIZER_AUTOMATON, automaton)\n    end)\nend)\n\nm:addOverride('xi.actions.abilities.pets.automaton.economizer.onAutomatonAbility', function(target, automaton, skill, master, action)\n    automaton:addRecast(xi.recast.ABILITY, skill:getID(), 180)\n\n    local darkManeuvers = master:countEffect(xi.effect.DARK_MANEUVER)\n    local mpRecovered   = math.floor(automaton:getMaxMP() * 0.2 * darkManeuvers)\n\n    for _ = 1, darkManeuvers do\n        master:delStatusEffectSilent(xi.effect.DARK_MANEUVER)\n    end\n\n    master:updateAttachments()\n\n    skill:setMsg(xi.msg.basic.SKILL_RECOVERS_MP)\n\n    return automaton:addMP(mpRecovered)\nend)\n"},["modules/era/lua/actions/abilities/pets/bloodpact_rage.lua"]={["Path"]="modules/era/lua/actions/abilities/pets/bloodpact_rage.lua",["SHA256"]="2f908549a5cb860e1574f23599183a105a003adb3e9339fb2ddaa69160008b6d",["Text"]="-----------------------------------\n-- Module: Blood Pact: Rage era adjustments\n-- Date : 2016 November 10th Patch\n-- Notes: https://wiki.ffo.jp/html/35795.html\n--        Multihit skills' fTPs were lowered but the first hit fTP carried over into subsequent hits.\n--        In 75 era, the subsequent hits had a 1.0 multiplier.\n--        Old fTPs might be lost to time unless there new data is uncovered through online documentation or client data.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_bloodpact_rage', xi.pre(xi.expansion.ROV))\n\n-----------------------------------\n-- Axe Kick\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.axe_kick.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Barracuda Dive\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.barracuda_dive.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Blindside\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.blindside.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    -- params.str_wSC           = 0.20 -- TODO: Capture wSCs\n    -- params.mnd_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Burning Strike\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.burning_strike.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage         = pet:getWeaponDmg()\n    params.numHits            = 1\n    params.fTP                = { 2.75, 2.75, 2.75 }\n    params.fTPSubsequentHits  = { 2.75, 2.75, 2.75 }\n    params.str_wSC            = 0.20\n    params.int_wSC            = 0.20\n    params.attackType         = xi.attackType.PHYSICAL\n    params.damageType         = xi.damageType.BLUNT\n    params.hybridSkill        = true\n    params.hybridSkillElement = xi.element.FIRE\n    params.hybridAttackType   = xi.attackType.MAGICAL\n    params.hybridDamageType   = xi.damageType.FIRE\n    params.shadowBehavior     = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    local totalDamage = 0\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        if info.damage > 0 then\n            target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n            totalDamage = totalDamage + info.damage\n        end\n\n        if info.hybridDamage > 0 and target:getHP() > 0 then\n            target:takeDamage(info.hybridDamage, pet, info.hybridAttackType, info.hybridDamageType)\n            totalDamage = totalDamage + info.hybridDamage\n        end\n    end\n\n    return totalDamage\nend)\n\n-----------------------------------\n-- Camisado\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.camisado.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.0, 2.0, 2.0 }\n    params.fTPSubsequentHits = { 2.0, 2.0, 2.0 }\n    params.str_wSC           = 0.20\n    params.mnd_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        -- TODO: Knockback may not yet be hooked up to abilities.\n        -- action:knockback(target:getID(), xi.action.knockback.LEVEL3)\n\n        -- TODO: Some equipment that reduces movement speed can reduce knockback distance. (Example: Plumb Boots)\n        -- https://discord.com/channels/392903136336936960/883227978002206751/1280243231635804262\n        -- https://discord.com/channels/443544205206355968/443893540922064896/1376405495845355661\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Chaotic Strike\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.chaotic_strike.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 10.00, 10.00, 10.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.20\n    params.int_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.STUN, power = 1, duration = 12, origin = pet },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Claw\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.claw.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Crag Throw\n-----------------------------------\n-- TODO: Not currently coded at time of this comment. Does not gain an accuracy bonus based on fTP.\n\n-----------------------------------\n-- Crescent Fang\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.crescent_fang.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 1.50, 1.50, 1.50 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.PARALYSIS, power = 22, duration = 60, origin = pet }, -- TODO: Capture power\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Double Punch\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.double_punch.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 2\n    params.fTP               = { 5.00, 5.00, 5.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_2\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Double Slap\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.double_slap.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 2\n    params.fTP               = { 6.328125, 6.328125, 6.328125 }\n    params.fTPSubsequentHits = { 1.000000, 1.000000, 1.000000 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_2\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Eclipse Bite\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.eclipse_bite.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 3.269531, 3.269531, 3.269531 }\n    params.fTPSubsequentHits = { 1.000000, 1.000000, 1.000000 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Flaming Crush\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.flaming_crush.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage         = pet:getWeaponDmg()\n    params.numHits            = 2\n    params.fTP                = { 6.00, 6.00, 6.00 }\n    params.fTPSubsequentHits  = { 1.00, 1.00, 1.00 }\n    params.str_wSC            = 0.20\n    params.int_wSC            = 0.20\n    params.attackType         = xi.attackType.PHYSICAL\n    params.damageType         = xi.damageType.BLUNT\n    params.hybridSkill        = true\n    params.hybridSkillElement = xi.element.FIRE\n    params.hybridAttackType   = xi.attackType.MAGICAL\n    params.hybridDamageType   = xi.damageType.FIRE\n    params.shadowBehavior     = xi.mobskills.shadowBehavior.NUMSHADOWS_2\n    params.primaryMessage     = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    local totalDamage = 0\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        if info.damage > 0 then\n            target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n            totalDamage = totalDamage + info.damage\n        end\n\n        if info.hybridDamage > 0 and target:getHP() > 0 then\n            target:takeDamage(info.hybridDamage, pet, info.hybridAttackType, info.hybridDamageType)\n            totalDamage = totalDamage + info.hybridDamage\n        end\n    end\n\n    return totalDamage\nend)\n\n-----------------------------------\n-- Megalith Throw\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.megalith_throw.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getRangedDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.375, 2.375, 2.375 }\n    params.fTPSubsequentHits = { 1.000, 1.000, 1.000 }\n    params.str_wSC           = 0.20\n    params.agi_wSC           = 0.20\n    params.skipParry         = true\n    params.skipGuard         = true\n    params.skipBlock         = true\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobRangedMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.SLOW, power = 3000, duration = 120, tier = 8, origin = pet }, -- TODO: Capture Slow tier\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Moonlit Charge\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.moonlit_charge.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 1.00, 1.00, 1.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.vit_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.BLINDNESS, power = 25, duration = 60, origin = pet },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Mountain Buster\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.mountain_buster.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 7.25, 7.25, 7.25 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.vit_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobRangedMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Poison Nails\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.poison_nails.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.PIERCING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.POISON, power = 1, tick = 3, duration = 90, tier = 1, origin = pet },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Predator Claws\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.predator_claws.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 10.00, 10.00, 10.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Punch\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.punch.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Regal Gash\n-----------------------------------\n-- TODO: Not coded at time of this comment. Loses accuracy ftp scaling.\n\n-----------------------------------\n-- Regal Scratch\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.regal_scratch.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    -- https://wiki.ffo.jp/html/26384.html\n    -- JP Wiki states that this skill was excluded from carrying first hit fTP to subsequent hits.\n    -- (See Patch note history for November 10th, 2016 in above link.)\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 3\n    params.fTP               = { 3.00, 3.00, 3.00 } -- TODO: Capture fTPs\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    -- params.dex_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_3\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Rock Buster\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.rock_buster.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.25, 2.25, 2.25 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.vit_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.BIND, power = 1, duration = 120, origin = pet }, -- TODO: Capture duration\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Rock Throw\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.rock_throw.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getRangedDmg()\n    params.numHits           = 1\n    params.fTP               = { 1.00, 1.00, 1.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.20\n    params.agi_wSC           = 0.20\n    params.skipParry         = true\n    params.skipGuard         = true\n    params.skipBlock         = true\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobRangedMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.SLOW, power = 3000, duration = 120, tier = 8, origin = pet }, -- TODO: Capture Slow tier\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Rush\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.rush.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 5\n    params.fTP               = { 3.50, 3.50, 3.50 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_5\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Shock Strike\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.shock_strike.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 2.00, 2.00, 2.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.20\n    params.int_wSC           = 0.20\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.STUN, power = 1, duration = 12, origin = pet },\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Spinning Dive\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.spinning_dive.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 7.01171, 7.01171, 7.01171 }\n    params.fTPSubsequentHits = { 1.00000, 1.00000, 1.00000 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.SLASHING\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Tail Whip\n-----------------------------------\nm:addOverride('xi.actions.abilities.pets.tail_whip.onPetAbility', function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local params = {}\n\n    params.baseDamage        = pet:getWeaponDmg()\n    params.numHits           = 1\n    params.fTP               = { 3.00, 3.00, 3.00 }\n    params.fTPSubsequentHits = { 1.00, 1.00, 1.00 }\n    params.str_wSC           = 0.30\n    params.attackType        = xi.attackType.PHYSICAL\n    params.damageType        = xi.damageType.BLUNT\n    params.shadowBehavior    = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.attackMultiplier  = { 2.0, 2.0, 2.0 }\n    params.primaryMessage    = xi.msg.basic.USES_JA_TAKE_DAMAGE\n\n    local info = xi.mobskills.mobPhysicalMove(pet, target, petskill, action, params)\n\n    if xi.mobskills.processDamage(pet, target, petskill, action, info) then\n        target:takeDamage(info.damage, pet, info.attackType, info.damageType)\n\n        local effectTable =\n        {\n            [1] = { effectId = xi.effect.WEIGHT, power = 50, duration = 120, tier = 1, origin = pet }, -- TODO: Capture power/duration/tier\n        }\n\n        xi.combat.action.executeMobskillStatusEffect(pet, target, petskill, effectTable, { messageBypass = true })\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Volt Strike\n-----------------------------------\n-- TODO: Volt Strike is not currently coded at time of this comment but should be set to 1.0 for fTPSubsequentHits. Loses Crit Scaling.\n"},["modules/era/lua/actions/abilities/pets/bloodpact_ward.lua"]={["Path"]="modules/era/lua/actions/abilities/pets/bloodpact_ward.lua",["SHA256"]="35947f9d6db562dfa73e26ec759a7af52d558ee33c8324bdb45208acb95a1300",["Text"]="-----------------------------------\n-- Module: Blood Pact: Ward era adjustments\n-- Reverts the doubled duration of wards and increased duration based on summoning magic skill over cap\n-- Source: http://www.playonline.com/pcd/update/ff11us/20061017UJ0a71/detail.html\n--         https://www.bg-wiki.com/ffxi/Version_Update_(09/08/2010)\n-- Notes : https://wiki.ffo.jp/html/14112.html\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_bloodpact_ward')\n\n-----------------------------------\n-- Shining Ruby\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.shining_ruby.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        -- TODO: BGWiki says this shares a buff slot with Rampart, Winds Blessing and One For All.\n        -- Need to capture tier priority.\n        -- https://www.bg-wiki.com/ffxi/Shining_Ruby\n        if target:hasStatusEffect(xi.effect.SHINING_RUBY) then\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT)\n\n            return xi.effect.SHINING_RUBY\n        end\n\n        local duration = 180\n\n        target:addStatusEffect(xi.effect.SHINING_RUBY, { power = 10, subPower = 390, duration = duration, origin = pet })\n\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n        end\n\n        return xi.effect.SHINING_RUBY\n    end,\n})\n\n-----------------------------------\n-- Hastega\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.hastega.onPetAbility', {\n    -- Reverts doubled base duration\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local baseDuration = 90\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet) * 3\n        local duration     = math.min(baseDuration + bonusTime, 180)\n\n        -- Old Notes:\n        -- Garuda's Hastega is a weird exception and uses 153/1024 instead of 150/1024 like Haste spell\n        -- That's why it overwrites some things regular haste won't. 153/1024 ~14.94%\n\n        -- Note from retail capture: WHM Haste spell and Garuda's Hastega will overwrite eachother.\n        if target:addStatusEffect(xi.effect.HASTE, { power = 1494, duration = duration, origin = pet }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n            return\n        end\n\n        return xi.effect.HASTE\n    end,\n\n    -- Reverts doubled base duration and Slow overwrites the Haste tier\n    -- Source: https://www.bg-wiki.com/ffxi/Version_Update_(04/08/2009)\n    [xi.expansion.WOTG] = function(target, pet, petskill, summoner, action)\n        local baseDuration = 90\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet) * 3\n        local duration     = math.min(baseDuration + bonusTime, 180)\n\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        if target:addStatusEffect(xi.effect.HASTE, { power = 1494, duration = duration, origin = pet, tier = 1 }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n            return\n        end\n\n        return xi.effect.HASTE\n    end,\n})\n\n-----------------------------------\n-- Crimson Howl\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.crimson_howl.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local baseDuration = 30\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet)\n        local duration     = math.min(baseDuration + bonusTime, 180)\n        local power        = (math.floor((pet:getMainLvl() / 4) + 4.75) / 256) * 100\n\n        if target:addStatusEffect(xi.effect.WARCRY, { power = power, duration = duration, origin = pet }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n            return\n        end\n\n        return xi.effect.WARCRY\n    end,\n})\n\n-----------------------------------\n-- Frost Armor\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.frost_armor.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        -- TODO: JPWiki says this will overwrite Reprisal. Possibly other spike effects.\n        target:delStatusEffect(xi.effect.ICE_SPIKES)\n\n        local baseDuration = 90\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet) * 3\n        local duration     = math.min(baseDuration + bonusTime, 180)\n\n        -- TODO: Does power ever scale?\n        if target:addStatusEffect(xi.effect.ICE_SPIKES, { power = 15, duration = duration, origin = pet }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n            return\n        end\n\n        return xi.effect.ICE_SPIKES\n    end,\n})\n\n-----------------------------------\n-- Glittering Ruby\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.glittering_ruby.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        -- Randomly gives STR/DEX/VIT/AGI/INT/MND/CHR\n        -- Can overwrite an existing Glittering Ruby effect\n        local effects =\n        {\n            xi.effect.STR_BOOST,\n            xi.effect.DEX_BOOST,\n            xi.effect.VIT_BOOST,\n            xi.effect.AGI_BOOST,\n            xi.effect.INT_BOOST,\n            xi.effect.MND_BOOST,\n            xi.effect.CHR_BOOST,\n        }\n\n        local effectId     = utils.randomEntry(effects)\n        local effectPower  = 3 + math.floor(pet:getMainLvl() / 5)\n        local baseDuration = 90\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet) * 3\n        local duration     = math.min(baseDuration + bonusTime, 180)\n\n        -- TODO: Ecliptic Growl does not overwrite this.\n        -- This does not overwrite Ecliptic Growl.\n        -- This can overwrite itself.\n        -- Unknown how it interacts with STAT_DOWN effects.\n        -- Unknown how it interacts with GAIN/BOOST spells.\n\n        if target:addStatusEffect(effectId, { power = effectPower, duration = duration, origin = pet }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n\n            return\n        end\n\n        return effectId\n    end,\n})\n\n-----------------------------------\n-- Rolling Thunder\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.rolling_thunder.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        local baseDuration = 60\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet) * 2\n        local duration     = math.min(baseDuration + bonusTime, 180)\n\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local magicskill = xi.data.skillLevel.getSkillCap(target:getMainLvl(), xi.skillRank.A_PLUS)\n        local potency    = 3 + 6 * magicskill / 100\n\n        if magicskill > 200 then\n            potency = 5 + 5 * magicskill / 100\n        end\n\n        xi.mobskills.mobBuffMove(target, xi.effect.ENTHUNDER, potency, 0, duration)\n\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.JA_RECEIVES_EFFECT_2)\n        else\n            petskill:setMsg(xi.msg.basic.JA_RECEIVES_EFFECT)\n        end\n\n        return xi.effect.ENTHUNDER\n    end,\n})\n\n-----------------------------------\n-- Lightning Armor\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.lightning_armor.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        local baseDuration = 90\n        local bonusTime    = xi.summon.getSummoningSkillOverCap(pet) * 3\n        local duration     = math.min(baseDuration + bonusTime, 180)\n\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        target:delStatusEffect(xi.effect.SHOCK_SPIKES)\n\n        if target:addStatusEffect(xi.effect.SHOCK_SPIKES, { power = 15, duration = duration, origin = pet }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n            return\n        end\n\n        return xi.effect.SHOCK_SPIKES\n    end,\n})\n\n-----------------------------------\n-- Ecliptic Growl\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.ecliptic_growl.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local duration  = 180\n        local moonCycle = getVanadielMoonCycle()\n\n        local cycleBuffs =\n        {\n            [xi.moonCycle.NEW_MOON]                = 1,\n            [xi.moonCycle.LESSER_WAXING_CRESCENT]  = 2,\n            [xi.moonCycle.GREATER_WAXING_CRESCENT] = 3,\n            [xi.moonCycle.FIRST_QUARTER]           = 4,\n            [xi.moonCycle.LESSER_WAXING_GIBBOUS]   = 5,\n            [xi.moonCycle.GREATER_WAXING_GIBBOUS]  = 6,\n            [xi.moonCycle.FULL_MOON]               = 7,\n            [xi.moonCycle.GREATER_WANING_GIBBOUS]  = 6,\n            [xi.moonCycle.LESSER_WANING_GIBBOUS]   = 5,\n            [xi.moonCycle.THIRD_QUARTER]           = 4,\n            [xi.moonCycle.GREATER_WANING_CRESCENT] = 3,\n            [xi.moonCycle.LESSER_WANING_CRESCENT]  = 2,\n        }\n\n        local buffValue = cycleBuffs[moonCycle]\n\n        target:delStatusEffect(xi.effect.STR_BOOST)\n        target:delStatusEffect(xi.effect.DEX_BOOST)\n        target:delStatusEffect(xi.effect.VIT_BOOST)\n        target:delStatusEffect(xi.effect.AGI_BOOST)\n        target:delStatusEffect(xi.effect.MND_BOOST)\n        target:delStatusEffect(xi.effect.CHR_BOOST)\n\n        target:addStatusEffect(xi.effect.STR_BOOST, { power = buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.DEX_BOOST, { power = buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.VIT_BOOST, { power = buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.AGI_BOOST, { power = 8 - buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.INT_BOOST, { power = 8 - buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.MND_BOOST, { power = 8 - buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.CHR_BOOST, { power = 8 - buffValue, duration = duration, origin = pet })\n\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.STATUS_BOOST)\n        else\n            petskill:setMsg(xi.msg.basic.STATUS_BOOST_2)\n        end\n\n        return 0\n    end,\n})\n\n-----------------------------------\n-- Ecliptic Howl\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.ecliptic_howl.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local duration  = 180\n        local moonCycle = getVanadielMoonCycle()\n\n        local cycleBuffs =\n        {\n            [xi.moonCycle.NEW_MOON]                = 1,\n            [xi.moonCycle.LESSER_WAXING_CRESCENT]  = 5,\n            [xi.moonCycle.GREATER_WAXING_CRESCENT] = 9,\n            [xi.moonCycle.FIRST_QUARTER]           = 13,\n            [xi.moonCycle.LESSER_WAXING_GIBBOUS]   = 17,\n            [xi.moonCycle.GREATER_WAXING_GIBBOUS]  = 21,\n            [xi.moonCycle.FULL_MOON]               = 25,\n            [xi.moonCycle.GREATER_WANING_GIBBOUS]  = 21,\n            [xi.moonCycle.LESSER_WANING_GIBBOUS]   = 17,\n            [xi.moonCycle.THIRD_QUARTER]           = 13,\n            [xi.moonCycle.GREATER_WANING_CRESCENT] = 9,\n            [xi.moonCycle.LESSER_WANING_CRESCENT]  = 5,\n        }\n\n        local buffValue = cycleBuffs[moonCycle]\n\n        target:delStatusEffect(xi.effect.ACCURACY_BOOST)\n        target:delStatusEffect(xi.effect.EVASION_BOOST)\n        target:addStatusEffect(xi.effect.ACCURACY_BOOST, { power = buffValue, duration = duration, origin = pet })\n        target:addStatusEffect(xi.effect.EVASION_BOOST, { power = 25 - buffValue, duration = duration, origin = pet })\n\n        if target:getID() == action:getPrimaryTargetID() then\n            petskill:setMsg(xi.msg.basic.ACC_EVA_BOOST)\n        else\n            petskill:setMsg(xi.msg.basic.ACC_EVA_BOOST_2)\n        end\n\n        return 0\n    end,\n})\n\n-----------------------------------\n-- Healing Ruby\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.healing_ruby.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local params = {}\n\n        params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n        params.baseHeal       = 3 * (pet:getMainLvl() - 30)\n        params.additiveHeal   = 44\n        params.fTP =\n        {\n            { tp = 0,    modifier = 256 / 256 },\n            { tp = 1500, modifier = 351 / 256 },\n            { tp = 3000, modifier = 446 / 256 },\n        }\n\n        if pet:getMainLvl() <= 30 then\n            params.baseHeal     = pet:getMainLvl()\n            params.additiveHeal = 14\n        end\n\n        return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\n    end,\n})\n\n-----------------------------------\n-- Healing Ruby II\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.healing_ruby_ii.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        -- https://wiki.ffo.jp/html/4080.html\n\n        local params = {}\n\n        params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n        params.baseHeal       = pet:getMainLvl() * 4\n        params.additiveHeal   = 30\n        params.fTP =\n        {\n            { tp = 0,    modifier = 256 / 256 },\n            { tp = 1500, modifier = 299 / 256 }, -- TODO: Unconfirmed for 75 era.\n            { tp = 3000, modifier = 342 / 256 },\n        }\n\n        return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\n    end,\n})\n\n-----------------------------------\n-- Noctoshield\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.noctoshield.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n        local duration = 180\n\n        if target:addStatusEffect(xi.effect.PHALANX, { power = 13, duration = duration, origin = pet }) then\n            if target:getID() == action:getPrimaryTargetID() then\n                petskill:setMsg(xi.msg.basic.SKILL_GAIN_EFFECT_2)\n            else\n                petskill:setMsg(xi.msg.basic.JA_GAIN_EFFECT)\n            end\n        else\n            petskill:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n            return\n        end\n\n        return xi.effect.PHALANX\n    end,\n})\n\n-----------------------------------\n-- Dream Shroud\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.dream_shroud.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n    xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n    local baseDuration = 180\n    local duration     = baseDuration\n    local hour         = VanadielHour()\n    local buffvalue    = math.abs(12 - hour) + 1\n\n    -- TODO: Does this overwrite itself?\n    target:delStatusEffect(xi.effect.MAGIC_ATK_BOOST)\n    target:delStatusEffect(xi.effect.MAGIC_DEF_BOOST)\n\n    target:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { power = buffvalue, duration = duration, origin = pet })\n    target:addStatusEffect(xi.effect.MAGIC_DEF_BOOST, { power = 14 - buffvalue, duration = duration, origin = pet })\n\n    if target:getID() == action:getPrimaryTargetID() then\n        petskill:setMsg(xi.msg.basic.JA_RECEIVES_MAB_MDB)\n    else\n        petskill:setMsg(xi.msg.basic.JA_RECEIVES_MAB_MDB_2)\n    end\n\n    return 0\n    end,\n})\n\n-----------------------------------\n-- Spring Water\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.spring_water.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local removableEffects =\n        {\n            xi.effect.BLINDNESS,\n            xi.effect.DISEASE,\n            xi.effect.PARALYSIS,\n            xi.effect.PETRIFICATION,\n            xi.effect.POISON,\n            xi.effect.SILENCE,\n            -- TODO: JPWiki mentions that Spring Water can remove Mute inflicted by Promathia. Need captures.\n            -- Mute inflicted from Eight of Cups mob could not be removed by this skill.\n        }\n\n        local activeEffects = {}\n\n        -- Fetch list of removable effects currently on target\n        for _, effectId in ipairs(removableEffects) do\n            if target:getStatusEffect(effectId) then\n                table.insert(activeEffects, effectId)\n            end\n        end\n\n        -- Remove one removable effect from the target, chosen at random\n        if #activeEffects > 0 then\n            activeEffects = utils.shuffle(activeEffects)\n\n            target:delStatusEffect(activeEffects[1])\n        end\n\n        local params = {}\n\n        params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n        params.baseHeal       = pet:getMainLvl() * 3\n        params.additiveHeal   = 47\n        params.fTP =\n        {\n            -- TODO: Heal formulas needs more research.\n            -- Using closest match for now.\n            { tp = 0,    modifier = 1024 / 1024 },\n            { tp = 1500, modifier = 1164 / 1024 },\n            { tp = 3000, modifier = 1304 / 1024 },\n        }\n\n        return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\n    end,\n})\n\n-----------------------------------\n-- Whispering Wind\n-----------------------------------\nm:addOverrideByEra('xi.actions.abilities.pets.whispering_wind.onPetAbility', {\n    [xi.expansion.ABYSSEA] = function(target, pet, petskill, summoner, action)\n        xi.job_utils.summoner.onUseBloodPact(target, pet, petskill, summoner, action)\n\n        local params = {}\n\n        params.primaryMessage = xi.msg.basic.JA_RECOVERS_HP_2\n        params.baseHeal       = pet:getMainLvl() * 2.5\n        params.additiveHeal   = 16\n        params.fTP =\n        {\n            { tp = 0,    modifier = 1024 / 1024 },\n            { tp = 1500, modifier = 1884 / 1024 },\n            { tp = 3000, modifier = 2240 / 1024 },\n        }\n\n        return xi.mobskills.mobHealMove(pet, target, petskill, action, params)\n    end,\n})\n"},["modules/era/lua/actions/weaponskills/automaton.lua"]={["Path"]="modules/era/lua/actions/weaponskills/automaton.lua",["SHA256"]="fdf08c0a083cd04748dd84e8cafdd439af9fb607f287637185e5c8efc4c360b7",["Text"]="-----------------------------------\n-- WoTG Era Automaton Weaponskills\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('wotg_automaton', xi.pre(xi.expansion.ABYSSEA))\n\n-----------------------------------\n-- Arcuballista\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.arcuballista.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage       = xi.automaton.getRangedBaseDamage(automaton)\n    params.numHits          = 1\n    params.fTP              = { 2.5, 3.0, 4.0 }\n    params.dex_wSC          = 0.30\n    params.accuracyModifier = { 100, 100, 100 }\n    params.attackType       = xi.attackType.RANGED\n    params.damageType       = xi.damageType.PIERCING\n    params.shadowBehavior   = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.skipParry        = true\n    params.skipGuard        = true\n    params.skipBlock        = true\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobRangedMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Armor Piercer\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.armor_piercer.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage       = xi.automaton.getRangedBaseDamage(automaton)\n    params.numHits          = 1\n    params.fTP              = { 3.0, 3.5, 4.0 }\n    params.dex_wSC          = 0.30\n    params.ignoreDefense    = { 0.5, 0.5, 0.5 }\n    params.accuracyModifier = { 100, 100, 100 }\n    params.attackType       = xi.attackType.RANGED\n    params.damageType       = xi.damageType.PIERCING\n    params.shadowBehavior   = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.skipParry        = true\n    params.skipGuard        = true\n    params.skipBlock        = true\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobRangedMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Bone Crusher\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.bone_crusher.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage     = automaton:getWeaponDmg()\n    params.numHits        = utils.clamp(3 + xi.automaton.getExtraHits(automaton, 3), 1, 8)\n    params.fTP            = { 1.5, 1.5, 1.5 }\n    params.vit_wSC        = 0.30\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.shadowBehavior = params.numHits\n\n    if target:isUndead() then\n        params.fTP = { 2.5, 2.5, 2.5 }\n    end\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(automaton, target, xi.effect.STUN, 1, 0, 4)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Cannibal Blade\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.cannibal_blade.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage         = automaton:getSkillLevel(xi.skill.AUTOMATON_MELEE) / 9.2\n    params.numHits            = 1\n    params.fTP                = { 11.0, 12.5, 14.0 }\n    params.attackType         = xi.attackType.PHYSICAL\n    params.damageType         = xi.damageType.SLASHING\n    params.shadowBehavior     = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.guaranteedFirstHit = true\n    params.skipFSTR           = true\n    params.skipPDIF           = true\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n\n        if not target:isUndead() then\n            automaton:addHP(info.damage)\n        end\n    end\n\n    -- Does not return TP.\n    automaton:setTP(0)\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Chimera Ripper\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.chimera_ripper.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage       = automaton:getWeaponDmg()\n    params.numHits          = utils.clamp(1 + xi.automaton.getExtraHits(automaton, 1), 1, 8)\n    params.fTP              = { 2.0, 2.5, 3.0 }\n    params.str_wSC          = 0.30\n    params.accuracyModifier = { 100, 100, 100 }\n    params.attackType       = xi.attackType.PHYSICAL\n    params.damageType       = xi.damageType.SLASHING\n    params.shadowBehavior   = params.numHits\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Daze\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.daze.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage       = xi.automaton.getRangedBaseDamage(automaton)\n    params.numHits          = 1\n    params.fTP              = { 5.0, 5.5, 6.0 }\n    params.dex_wSC          = 0.30\n    params.accuracyModifier = { 150, 150, 150 }\n    params.attackType       = xi.attackType.RANGED\n    params.damageType       = xi.damageType.PIERCING\n    params.shadowBehavior   = xi.mobskills.shadowBehavior.NUMSHADOWS_1\n    params.skipParry        = true\n    params.skipGuard        = true\n    params.skipBlock        = true\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobRangedMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(automaton, target, xi.effect.STUN, 1, 0, 4)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Knockout\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.knockout.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.numHits          = utils.clamp(1 + xi.automaton.getExtraHits(automaton, 1), 1, 8)\n    params.fTP              = { 4.0, 4.5, 5.0 }\n    params.agi_wSC          = 0.40\n    params.accuracyModifier = { 50, 50, 50 }\n    params.attackType       = xi.attackType.PHYSICAL\n    params.damageType       = xi.damageType.BLUNT\n    params.shadowBehavior   = params.numHits\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n\n        xi.mobskills.mobStatusEffectMove(automaton, target, xi.effect.EVASION_DOWN, 20, 0, 30)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Magic Mortar\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.magic_mortar.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage     = automaton:getMaxHP() - automaton:getHP()\n    params.fTP            = { 0.50, 0.75, 1.00 }\n    params.element        = xi.element.NONE\n    params.attackType     = xi.attackType.MAGICAL\n    params.damageType     = xi.damageType.ELEMENTAL\n    params.shadowBehavior = xi.mobskills.shadowBehavior.IGNORE_SHADOWS\n\n    -- Flame Holder multiplies the base damage of Magic Mortar. Gives a 25% boost at 3 Fire Maneuvers.\n    local flameHolderModifier = 1.0 + (automaton:getMod(xi.mod.WEAPONSKILL_DAMAGE_BASE) - 100) / 1000\n\n    if flameHolderModifier > 1.0 then\n        params.baseDamage = math.floor(params.baseDamage * flameHolderModifier)\n    end\n\n    local info = xi.mobskills.mobMagicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- Slapstick\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.slapstick.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.numHits          = utils.clamp(3 + xi.automaton.getExtraHits(automaton, 3), 1, 8)\n    params.fTP              = { 1.0, 1.0, 1.0 }\n    params.str_wSC          = 0.20\n    params.dex_wSC          = 0.20\n    params.accuracyModifier = { 0, 30, 50 }\n    params.attackType       = xi.attackType.PHYSICAL\n    params.damageType       = xi.damageType.BLUNT\n    params.shadowBehavior   = params.numHits\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n\n-----------------------------------\n-- String Clipper\n-----------------------------------\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.actions.abilities.pets.automaton.string_clipper.onAutomatonAbility', function(target, automaton, skill, master, action)\n    local params = {}\n\n    params.baseDamage       = automaton:getWeaponDmg()\n    params.numHits          = utils.clamp(2 + xi.automaton.getExtraHits(automaton, 2), 1, 8)\n    params.fTP              = { 2.0, 2.0, 2.0 }\n    params.str_wSC          = 0.15\n    params.dex_wSC          = 0.15\n    params.attackMultiplier = { 1.5, 1.5, 1.5 }\n    params.accuracyModifier = { 0, 50, 100 }\n    params.attackType       = xi.attackType.PHYSICAL\n    params.damageType       = xi.damageType.SLASHING\n    params.shadowBehavior   = params.numHits\n\n    xi.automaton.applyFlameHolder(automaton, params.fTP)\n\n    local info = xi.mobskills.mobPhysicalMove(automaton, target, skill, action, params)\n\n    if xi.mobskills.processDamage(automaton, target, skill, action, info) then\n        target:takeDamage(info.damage, automaton, info.attackType, info.damageType)\n    end\n\n    return info.damage\nend)\n"},["modules/era/lua/globals/job_utils/beastmaster.lua"]={["Path"]="modules/era/lua/globals/job_utils/beastmaster.lua",["SHA256"]="eddb6762502c42506f85e49983740a03f2de5c616311e87fba6d025d29834613",["Text"]="-----------------------------------\n-- Module: Beastmaster Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_beastmaster')\n\n-- Reward: Override pet food healing values to pre-Abyssea values\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(09/08/2010)\nm:addOverrideByEra('xi.server.onServerStart', {\n    [xi.expansion.ABYSSEA] = function()\n        super()\n\n        xi.job_utils.beastmaster.petFoodData =\n        {\n            [xi.item.PET_FOOD_ALPHA_BISCUIT]   = { minHealing =  25, regen = 1, mndMult = 2, mndThreshold = 10 },\n            [xi.item.PET_FOOD_BETA_BISCUIT]    = { minHealing =  50, regen = 2, mndMult = 1, mndThreshold = 33 },\n            [xi.item.PET_FOOD_GAMMA_BISCUIT]   = { minHealing = 100, regen = 3, mndMult = 1, mndThreshold = 35 },\n            [xi.item.PET_FOOD_DELTA_BISCUIT]   = { minHealing = 150, regen = 4, mndMult = 2, mndThreshold = 40 },\n            [xi.item.PET_FOOD_EPSILON_BISCUIT] = { minHealing = 300, regen = 5, mndMult = 2, mndThreshold = 45 },\n            [xi.item.PET_FOOD_ZETA_BISCUIT]    = { minHealing = 350, regen = 6, mndMult = 3, mndThreshold = 45 },\n        }\n    end,\n})\n\n-- Feral Howl: Apply merit recast reduction, remove extra accuracy from merits\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.beastmaster.useFeralHowl', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.FERAL_HOWL) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        if\n            not xi.data.statusEffect.isTargetImmune(target, xi.effect.TERROR, xi.element.DARK) and\n            not xi.data.statusEffect.isTargetResistant(player, target, xi.effect.TERROR) and\n            not xi.data.statusEffect.isEffectNullified(target, xi.effect.TERROR, 0)\n        then\n            local maccParams =\n            {\n                effectId       = xi.effect.TERROR,\n                magicalElement = xi.element.DARK,\n                skillRank      = xi.skillRank.B_MINUS,\n                actorStat      = xi.mod.CHR,\n            }\n\n            local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n\n            if xi.data.statusEffect.isResistRateSuccessfull(xi.effect.TERROR, resistanceRate, 0) then\n                target:addStatusEffect(xi.effect.TERROR, { power = 1, duration = 10 * resistanceRate, origin = player })\n            end\n        end\n\n        return xi.effect.TERROR\n    end,\n})\n\n-- Killer Insinct: Apply merit recast reduction, remove extra duration from merits\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.beastmaster.useKillerInstinct', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.KILLER_INSTINCT) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        -- Notes: Pet ecosystem is assigned to the subPower, then mapped to the correct killer mod in the effect script.\n        local pet          = player:getPet()\n        local petEcosystem = pet:getEcosystem()\n        local power        = 10\n\n        target:addStatusEffect(xi.effect.KILLER_INSTINCT, { power = power, duration = 60, origin = player, subPower = petEcosystem })\n\n        return xi.effect.KILLER_INSTINCT\n    end,\n})\n"},["modules/era/lua/globals/job_utils/corsair.lua"]={["Path"]="modules/era/lua/globals/job_utils/corsair.lua",["SHA256"]="3f1593dfca8144a918573a1f0f62a3fc93dbed6649b833b7913848f56c7a5425",["Text"]="-----------------------------------\n-- Module: Corsair Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_corsair')\n\n-- Beast Roll: Remove pet ranged attack\n-- Source: https://forum.square-enix.com/ffxi/threads/48564-Sep-16-2015-%28JST%29-Version-Update\nm:addOverrideByEra('xi.effects.beast_roll.onEffectGain', {\n    [xi.expansion.ROV] = function(target, effect)\n        target:addPetMod(xi.mod.ATTP, effect:getPower())\n    end,\n})\n\nm:addOverrideByEra('xi.effects.beast_roll.onEffectLose', {\n    [xi.expansion.ROV] = function(target, effect)\n        target:delPetMod(xi.mod.ATTP, effect:getPower())\n        xi.job_utils.corsair.onRollEffectLose(target, effect)\n    end,\n})\n\n-- Phantom Roll powers and bonus changed in the SoA era\n-- Source: https://forum.square-enix.com/ffxi/threads/41814-May-15-2014-%28JST%29-Version-Update\nlocal soaRollData =\n{\n    [xi.jobAbility.NINJA_ROLL] =\n    {\n        powers = { 4, 6,  8, 25, 10, 12, 14, 2, 17, 20, 30, 8 },\n        bonus  = 10,\n    },\n\n    [xi.jobAbility.WIZARDS_ROLL] =\n    {\n        powers = { 2, 3,  4,  4, 10,  5,  6, 7,  1,  7, 12, 4 },\n        bonus  = 4,\n    },\n\n    [xi.jobAbility.DANCERS_ROLL] =\n    {\n        powers = { 3, 4, 11,  4,  5,  6,  1, 7,  8,  8, 14, 3 },\n        bonus  = 3,\n    },\n}\n\n-- Phantom Roll powers and bonuses differ before the Abyssea era.\n-- Source: https://forum.square-enix.com/ffxi/threads/20744?p=278735#post278735\nlocal abysseaRollData =\n{\n    [xi.jobAbility.WARLOCKS_ROLL] =\n    {\n        powers = {  2,  3,  4, 10,  4,  5,  6,  1,  7,  7, 12,  4 },\n        bonus  = 4,\n    },\n\n    [xi.jobAbility.BEAST_ROLL] =\n    {\n        powers = {  5,  6,  7, 19,  8,  9, 12,  2, 13, 14, 23,  8 },\n        bonus  = 8,\n    },\n\n    [xi.jobAbility.CHORAL_ROLL] =\n    {\n        powers = {  4, 17,  5,  6,  7,  2,  8, 10, 11, 12, 21,  8 },\n        bonus  = 8,\n    },\n\n    [xi.jobAbility.DANCERS_ROLL] =\n    {\n        powers = {  3,  4, 11,  4,  5,  6,  1,  7,  8,  8, 14,  3 },\n        bonus  = 3,\n    },\n\n    [xi.jobAbility.HEALERS_ROLL] =\n    {\n        powers = {  2,  3, 10,  4,  4,  5,  1,  6,  7,  7, 12,  3 },\n        bonus  = 3,\n    },\n\n    [xi.jobAbility.GALLANTS_ROLL] =\n    {\n        powers = {  4,  5, 15,  6,  7,  8,  3,  9, 10, 12, 20, 10 },\n        bonus  = 10,\n    },\n\n    [xi.jobAbility.DRACHEN_ROLL] =\n    {\n        powers = {  4,  5, 18,  7,  9, 10,  2, 11, 13, 15, 22,  8 },\n        bonus  = 8,\n    },\n\n    [xi.jobAbility.PUPPET_ROLL] =\n    {\n        powers = { 10, 13, 15, 40, 18, 20, 25,  5, 28, 30, 50, 15 },\n        bonus  = 15,\n    },\n}\n\nm:addOverrideByEra('xi.server.onServerStart', {\n    [xi.expansion.SOA] = function()\n        super()\n\n        local rollModData = xi.job_utils.corsair.rollData\n\n        for abilityId, data in pairs(soaRollData) do\n            local rollInfo  = rollModData[abilityId]\n            rollInfo.powers = data.powers\n            rollInfo.bonus  = data.bonus\n        end\n    end,\n\n    [xi.expansion.ABYSSEA] = function()\n        super()\n\n        local rollData = xi.job_utils.corsair.rollData\n\n        for abilityId, data in pairs(abysseaRollData) do\n            local rollInfo  = rollData[abilityId]\n            rollInfo.powers = data.powers\n            rollInfo.bonus  = data.bonus\n        end\n\n        -- Light Shot / Dark Shot: Revert Dia and Bio subpower baselines to pre-April-2019 values (5/10/15 instead of 10/15/20).\n        -- Source: https://forum.square-enix.com/ffxi/threads/55263-April.-3-2019-%28JST%29-Version-Update\n        local diaBasePowerByTier = xi.job_utils.corsair.quickDrawEffectBoostTable[xi.jobAbility.LIGHT_SHOT][1].basePowerByTier\n        diaBasePowerByTier[1] = 5\n        diaBasePowerByTier[3] = 10\n        diaBasePowerByTier[5] = 15\n\n        local bioBasePowerByTier = xi.job_utils.corsair.quickDrawEffectBoostTable[xi.jobAbility.DARK_SHOT][1].basePowerByTier\n        bioBasePowerByTier[2] = 5\n        bioBasePowerByTier[4] = 10\n        bioBasePowerByTier[6] = 15\n    end,\n})\n\n-- Light Shot / Dark Shot: Revert Dia and Bio effect boost to +5% defense/attack down instead of +2%.\n-- Source: https://forum.square-enix.com/ffxi/threads/55263-April.-3-2019-%28JST%29-Version-Update\nm:addOverrideByEra('xi.job_utils.corsair.handleQuickDrawEffectBoost', {\n    [xi.expansion.ABYSSEA] = function(player, target, abilityId, multiplier)\n        local effectData = xi.job_utils.corsair.quickDrawEffectBoostTable[abilityId]\n        if not effectData then\n            return\n        end\n\n        -- Gather eligible effects that have not yet been boosted.\n        local effects = {}\n        for _, entryTable in ipairs(effectData) do\n            local effectChecked = target:getStatusEffect(entryTable.effectId)\n\n            if effectChecked then\n                local eligible = false\n\n                -- Check for Dia/Bio.\n                if entryTable.basePowerByTier then\n                    local basePower = entryTable.basePowerByTier[effectChecked:getTier()]\n                    eligible        = basePower and effectChecked:getSubPower() <= basePower\n\n                -- Check for all other eligible effects\n                else\n                    eligible = effectChecked:getPower() < entryTable.capGlobal\n                end\n\n                if eligible then\n                    table.insert(effects, { effect = effectChecked, entry = entryTable })\n                end\n            end\n        end\n\n        -- Early return: No effect can be boosted, either because it's capped or isn't present.\n        if #effects <= 0 then\n            return\n        end\n\n        -- Select effect entry from table and fetch it's content.\n        local selected = effects[math.randomInt(1, #effects)]\n        local effect   = selected.effect\n        local entry    = selected.entry\n\n        -- Fetch effect data.\n        local effectId        = effect:getEffectType()\n        local effectPower     = effect:getPower()\n        local effectTick      = effect:getTick() / 1000\n        local effectDuration  = effect:getDuration() / 1000\n        local effectSubPower  = effect:getSubPower()\n        local effectSubType   = effect:getSubType()\n        local effectTier      = effect:getTier()\n        local effectStartTime = effect:getStartTime()\n        local effectOriginID  = effect:getOriginID()\n\n        -- Apply boost to Dia or Bio effects. They can only be boosted once. \"Cannot be stacked.\"\n        if entry.basePowerByTier then\n            if effectId == xi.effect.DIA then\n                effectPower = effectPower + 1\n            end\n\n            effectSubPower = effectSubPower + 5\n\n        -- Apply boost to all other eligible effects.\n        else\n            if effectId >= xi.effect.BURN and effectId <= xi.effect.DROWN then\n                effectPower = math.min(effectPower + 2, entry.capGlobal)\n            else\n                effectPower = math.min(effectPower * multiplier, entry.capGlobal)\n            end\n        end\n\n        -- Remove the existing effect and reapply it with the new power/subPower values.\n        target:delStatusEffectSilent(effectId)\n\n        local params =\n        {\n            power    = effectPower,\n            tick     = effectTick,\n            duration = effectDuration,\n            subPower = effectSubPower,\n            subType  = effectSubType,\n            tier     = effectTier,\n            origin   = player,\n        }\n\n        target:addStatusEffect(effectId, params)\n\n        -- Update the start time and origin ID of the new effect to match the original effect.\n        local newEffect = target:getStatusEffect(effectId)\n        if newEffect then\n            newEffect:setStartTime(effectStartTime)\n            newEffect:setOriginID(effectOriginID)\n        end\n    end,\n})\n\n-- Healer's Roll: Revert from Cure potency bonus to MP heal bonus\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.healers_roll.onEffectGain', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        effect:addMod(xi.mod.MPHEAL, effect:getPower())\n    end,\n})\n\n-- Gallant's Roll: Revert to proportional damage reflection relative to damage taken.\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.gallants_roll.onEffectGain', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        effect:addMod(xi.mod.SPIKES, xi.subEffect.BLAZE_SPIKES)\n        target:addListener('TAKE_DAMAGE', 'GALLANTS_ROLL_REFLECT', function(entity, amount, attacker, attackType, damageType)\n            if\n                amount > 0 and\n                attackType == xi.attackType.PHYSICAL\n            then\n                entity:setMod(xi.mod.SPIKES_DMG, math.floor(amount * effect:getPower() / 100))\n            end\n        end)\n    end,\n})\n\nm:addOverrideByEra('xi.effects.gallants_roll.onEffectLose', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        target:removeListener('GALLANTS_ROLL_REFLECT')\n        target:setMod(xi.mod.SPIKES_DMG, 0)\n        super(target, effect)\n    end,\n})\n\n-- Drachen Roll: Revert from Pet Accuracy bonus to Pet Magic Acc/Attack bonus\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.drachen_roll.onEffectGain', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        target:addPetMod(xi.mod.MATT, effect:getPower())\n        target:addPetMod(xi.mod.MACC, effect:getPower())\n    end,\n})\n\nm:addOverrideByEra('xi.effects.drachen_roll.onEffectLose', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        target:delPetMod(xi.mod.MATT, effect:getPower())\n        target:delPetMod(xi.mod.MACC, effect:getPower())\n        xi.job_utils.corsair.onRollEffectLose(target, effect)\n    end,\n})\n\n-- Puppet Roll: Revert from Pet Magic Acc/Attack bonus to Pet Accuracy bonus\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.puppet_roll.onEffectGain', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        target:addPetMod(xi.mod.ACC, effect:getPower())\n        target:addPetMod(xi.mod.RACC, effect:getPower())\n    end,\n})\n\nm:addOverrideByEra('xi.effects.puppet_roll.onEffectLose', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        target:delPetMod(xi.mod.ACC, effect:getPower())\n        target:delPetMod(xi.mod.RACC, effect:getPower())\n        xi.job_utils.corsair.onRollEffectLose(target, effect)\n    end,\n})\n\n-- Phantom Roll XI bonus: Reverts various bonuses added to rolling and having an XI effect active\n-- - Disable reduced recast while an XI is active.\n-- - Disable bust effect prevention while an XI is active.\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(03/26/2012)\nm:addOverrideByEra('xi.job_utils.corsair.checkForElevenRoll', {\n    [xi.expansion.ABYSSEA] = function(caster)\n        return false\n    end,\n})\n\n-- - Disable Phantom Roll recast reset when landing on XI via Double-Up.\nm:addOverrideByEra('xi.job_utils.corsair.useDoubleUp', {\n    [xi.expansion.ABYSSEA] = function(caster, target, ability, action)\n        if caster:getID() == target:getID() then -- the COR handles all the calculations\n            local duEffect = caster:getStatusEffect(xi.effect.DOUBLE_UP_CHANCE)\n            local prevRoll = caster:getStatusEffect(duEffect:getSubPower())\n            local roll     = prevRoll:getSubPower()\n            local job      = duEffect:getTier()\n\n            caster:setLocalVar('corsairActiveRoll', duEffect:getSourceTypeParam())\n\n            local snakeEye = caster:getStatusEffect(xi.effect.SNAKE_EYE)\n\n            if snakeEye then\n                if roll >= 5 and math.randomInt(1, 100) < snakeEye:getPower() then\n                    roll = 11\n                else\n                    roll = roll + 1\n                end\n\n                caster:delStatusEffect(xi.effect.SNAKE_EYE)\n            else\n                roll = roll + math.randomInt(1, 6)\n            end\n\n            if roll >= 12 then -- bust\n                roll = 12\n                caster:delStatusEffectSilent(xi.effect.DOUBLE_UP_CHANCE)\n            end\n\n            caster:setLocalVar('corsairRollTotal', roll)\n            action:info(caster:getID(), roll - prevRoll:getSubPower())\n            xi.job_utils.corsair.checkForJobBonus(caster, job)\n        end\n\n        local total       = caster:getLocalVar('corsairRollTotal')\n        local activeRoll  = caster:getLocalVar('corsairActiveRoll')\n        local prevAbility = GetAbility(activeRoll)\n\n        if prevAbility then -- Apply rolls to target(s), including the COR\n            action:actionID(prevAbility:getID())\n\n            total = xi.job_utils.corsair.applyRoll(caster, target, prevAbility, total, true, ability)\n\n            if total > 11 then\n                action:setAnimation(target:getID(), 98) -- 98 is bust anim for all rolls\n            else\n                action:setAnimation(target:getID(), prevAbility:getAnimation())\n            end\n\n            return total\n        end\n    end,\n})\n\n-- Snake Eye: Revert to cooldown reduction from merit points, remove bonus free XI effect.\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(05/15/2012)\n-- Merit value is set to 150s/level by modules/era/sql/abyssea/job_adjustments.sql\nm:addOverrideByEra('xi.job_utils.corsair.useSnakeEye', {\n    [xi.expansion.ABYSSEA] = function(player, action)\n        local recastReduction = player:getMerit(xi.merit.SNAKE_EYE) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        player:addStatusEffect(xi.effect.SNAKE_EYE, { power = 0, duration = 60, origin = player })\n\n        return xi.effect.SNAKE_EYE\n    end,\n})\n\n-- Fold: Revert to cooldown reduction from merit points, remove bonus phantom roll reset.\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.corsair.useFold', {\n    [xi.expansion.ABYSSEA] = function(player, action)\n        local sourceId   = player:getID()\n        local newestBust = nil\n        local newestRoll = nil\n        local bustExpiry = 0\n        local rollExpiry = 0\n\n        for _, effect in pairs(player:getStatusEffects()) do\n            local effectType = effect:getEffectType()\n            local expiry     = effect:getStartTime() + effect:getDuration() / 1000\n\n            if\n                effectType == xi.effect.BUST and\n                (newestBust == nil or expiry > bustExpiry)\n            then\n                newestBust = effect\n                bustExpiry = expiry\n            elseif\n                effect:hasEffectFlag(xi.effectFlag.ROLL) and\n                effect:getSourceTypeParam() == sourceId and\n                (newestRoll == nil or expiry > rollExpiry)\n            then\n                newestRoll = effect\n                rollExpiry = expiry\n            end\n        end\n\n        local selected = newestBust or newestRoll\n\n        if selected ~= nil then\n            player:delStatusEffect(selected:getEffectType())\n            player:delStatusEffectSilent(xi.effect.DOUBLE_UP_CHANCE)\n\n            -- Merit value is set to 150s/level by modules/era/sql/abyssea/job_adjustments.sql\n            local recastReduction = player:getMerit(xi.merit.FOLD) - 150\n            action:setRecast(action:getRecast() - recastReduction)\n        end\n    end,\n})\n\n-- Elemental Shot: Revert TP gain and Marksmanship skillup added to Quick Draw.\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(09/08/2010)\nm:addOverrideByEra('xi.job_utils.corsair.useElementalShot', {\n    [xi.expansion.ABYSSEA] = function(actor, target, ability, action)\n        local abilityId = ability:getID()\n\n        -- Fetch specific ability data.\n        local data = xi.job_utils.corsair.quickDrawDataTable[abilityId]\n        if not data then\n            return\n        end\n\n        -- Handle card consumption.\n        if not actor:delItem(data.cardAmmo, 1) then\n            actor:delItem(xi.item.TRUMP_CARD, 1)\n        end\n\n        -- Handle recast.\n        action:setRecast(math.max(0, action:getRecast() - actor:getMod(xi.mod.QUICK_DRAW_RECAST)))\n\n        -- Handle claim.\n        target:updateClaim(actor)\n\n        -- Calculate resist rate.\n        local bonusAcc   = actor:getMerit(xi.merit.QUICK_DRAW_ACCURACY) + actor:getMod(xi.mod.QUICK_DRAW_MACC)\n        local maccParams =\n        {\n            effectId       = data.applyEffectId or 0,\n            magicalElement = data.element,\n            skillType      = xi.skill.MARKSMANSHIP,\n            actorStat      = xi.mod.AGI,\n            bonusMacc      = bonusAcc,\n        }\n\n        local resist = xi.combat.magicHitRate.calculateResistRate(actor, target, maccParams)\n\n        -- Handle damage.\n        local damage = 0\n        if data.canDamage then\n            damage = xi.job_utils.corsair.handleQuickDrawDamage(actor, target, action, data.element, resist)\n        end\n\n        -- Handle effect boost.\n        xi.job_utils.corsair.handleQuickDrawEffectBoost(actor, target, abilityId, data.multiplier)\n\n        -- Handle effect application.\n        if data.applyEffectId > 0 then\n            if\n                xi.data.statusEffect.isTargetImmune(target, data.applyEffectId, data.element) or\n                xi.data.statusEffect.isTargetResistant(actor, target, data.applyEffectId) or\n                not xi.data.statusEffect.isResistRateSuccessfull(data.applyEffectId, resist, 0)\n            then\n                ability:setMsg(xi.msg.basic.JA_MISS_2)\n                return data.applyEffectId\n            end\n\n            -- Light shot.\n            if data.applyEffectId == xi.effect.SLEEP_I then\n                if target:addStatusEffect(xi.effect.SLEEP_I, { power = 1, duration = math.floor(90 * resist), subPower = data.element, origin = actor }) then\n                    ability:setMsg(xi.msg.basic.JA_ENFEEB_IS)\n                else\n                    ability:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n                end\n\n                return xi.effect.SLEEP_I\n\n            -- Dark shot.\n            else\n                ability:setMsg(xi.msg.basic.JA_REMOVE_EFFECT_2)\n\n                local dispelledEffect = target:dispelStatusEffect()\n                if dispelledEffect == xi.effect.NONE then\n                    ability:setMsg(xi.msg.basic.JA_NO_EFFECT_2)\n                end\n\n                return dispelledEffect\n            end\n        end\n\n        return damage\n    end,\n})\n"},["modules/era/lua/globals/job_utils/dark_knight.lua"]={["Path"]="modules/era/lua/globals/job_utils/dark_knight.lua",["SHA256"]="c929ff9df0233438ed64b0806978633486e767ed03324ecc37078d241571b71c",["Text"]="-----------------------------------\n-- Module: Dark Knight Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_dark_knight')\n\n-- Last Resort: Reduces attack bonus from 25% to 15%\n-- Source: https://forum.square-enix.com/ffxi/threads/46976-May-14-2015-%28JST%29-Version-Update\nm:addOverrideByEra('xi.effects.last_resort.onEffectGain', {\n    [xi.expansion.SOA] = function(target, effect)\n        local targetMerit = target:getMerit(xi.merit.LAST_RESORT_EFFECT)\n\n        effect:addMod(xi.mod.ATTP, 15 + targetMerit)\n        effect:addMod(xi.mod.RATTP, 15 + targetMerit)\n        effect:addMod(xi.mod.DEFP, -15 - targetMerit)\n        effect:addMod(xi.mod.TWOHAND_HASTE_ABILITY, target:getMod(xi.mod.DESPERATE_BLOWS) + target:getMerit(xi.merit.DESPERATE_BLOWS))\n    end,\n})\n\n-- Arcane Circle: Revert duration from 3 minutes to 1 minute\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(02/13/2012)\nm:addOverrideByEra('xi.job_utils.dark_knight.useArcaneCircle', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability)\n        local duration = 60 + player:getMod(xi.mod.ARCANE_CIRCLE_DURATION)\n        local power    = 15\n\n        if player:getMainJob() ~= xi.job.DRK then\n            power = 5\n        end\n\n        power = power + player:getMod(xi.mod.ARCANE_CIRCLE_POTENCY)\n\n        target:addStatusEffect(xi.effect.ARCANE_CIRCLE, { power = power, duration = duration, origin = player })\n\n        return xi.effect.ARCANE_CIRCLE\n    end,\n})\n\n-- Last Resort: Revert duration from 3 minutes to 30 seconds\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.dark_knight.useLastResort', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability)\n        player:addStatusEffect(xi.effect.LAST_RESORT, { duration = 30, origin = player })\n\n        return xi.effect.LAST_RESORT\n    end,\n})\n\n-- Dark Seal: Remove extra duration and cast speed from merits\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.dark_seal.onEffectGain', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        -- Overwrites\n        target:delStatusEffectSilent(xi.effect.DIVINE_EMBLEM)\n        target:delStatusEffectSilent(xi.effect.DIVINE_SEAL)\n        target:delStatusEffectSilent(xi.effect.ELEMENTAL_SEAL)\n    end,\n})\n\n-- Dark Seal: Apply merit recast reduction\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.dark_knight.useDarkSeal', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.DARK_SEAL) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        player:addStatusEffect(xi.effect.DARK_SEAL, { power = 1, duration = 60, origin = player })\n\n        return xi.effect.DARK_SEAL\n    end,\n})\n\n-- Diabolic Eye: Remove extra duration and potency from merits and apply merit recast reduction\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.dark_knight.useDiabolicEye', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.DIABOLIC_EYE) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        player:addStatusEffect(xi.effect.DIABOLIC_EYE, { power = 20, duration = 180, origin = player })\n\n        return xi.effect.DIABOLIC_EYE\n    end,\n})\n\n-- Arcane Circle: Removes WotG resist/defense/attack circle mods\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(07/20/2009)\nm:addOverrideByEra('xi.effects.arcane_circle.onEffectGain', {\n    [xi.expansion.WOTG] = function(target, effect)\n        effect:addMod(xi.mod.ARCANA_KILLER, effect:getPower())\n    end,\n})\n"},["modules/era/lua/globals/job_utils/dragoon.lua"]={["Path"]="modules/era/lua/globals/job_utils/dragoon.lua",["SHA256"]="8fdf0b6ef7136e5cbda83b21ebcc3a029cee115736cd1cc7ee7257802ba51919",["Text"]="-----------------------------------\n-- Module: Dragoon Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_dragoon')\n\n-- Each override declares one implementation per era, keyed by xi.expansion.\n-- A case applies when its content is disabled. The loader orders cases\n-- newest era first, so the oldest applicable era ends up outermost and its\n-- super chain reaches back through the newer reverts.\n\n-- Healing Breath: Revert to consume TP and formula based on TP usage\n-- Source: https://forum.square-enix.com/ffxi/threads/52969\nm:addOverrideByEra('xi.job_utils.dragoon.useHealingBreath', {\n    [xi.expansion.ROV] = function(wyvern, target, skill, action)\n        local healingBreathTable =\n        {\n            --                                    { base, multiplier }\n            [xi.jobAbility.HEALING_BREATH]     = {  8, 25 },\n            [xi.jobAbility.HEALING_BREATH_II]  = { 24, 38 },\n            [xi.jobAbility.HEALING_BREATH_III] = { 42, 45 },\n            [xi.jobAbility.HEALING_BREATH_IV]  = { 60, 53 },\n        }\n\n        local master              = wyvern:getMaster()\n        local deepMult            = xi.job_utils.dragoon.getDeepBreathingBonus(wyvern, master, true)\n        local jobPointBonus       = master:getJobPointLevel(xi.jp.WYVERN_BREATH_EFFECT) * 10\n        local breathAugmentsBonus = 1 + master:getMod(xi.mod.UNCAPPED_WYVERN_BREATH) / 100\n        local gear                = master:getMod(xi.mod.WYVERN_BREATH) -- Master gear that enhances breath\n        local base                = healingBreathTable[skill:getID()][1]\n        local baseMultiplier      = healingBreathTable[skill:getID()][2]\n\n        -- TP bonus: wyvern TP enhances healing multiplier\n        local tpBonus = math.floor(wyvern:getTP() / 200) / 1.165\n\n        -- gear cap of 64/256 in multiplier\n        local multiplier      = (baseMultiplier + math.min(gear, 64) + math.floor(deepMult) + tpBonus) / 256\n        local curePower       = math.floor(wyvern:getMaxHP() * multiplier) + base + jobPointBonus * breathAugmentsBonus\n        local totalHPRestored = target:addHP(curePower)\n\n        -- Consume wyvern TP after calculating breath power\n        wyvern:setTP(0)\n\n        skill:setMsg(xi.msg.basic.JA_RECOVERS_HP_2)\n\n        -- Also cure the Wyvern if Spirit Bond is up\n        if master:hasStatusEffect(xi.effect.SPIRIT_BOND) then\n            local totalWyvernHPRestored = wyvern:addHP(curePower)\n\n            action:addAdditionalTarget(wyvern:getID())\n            action:setAnimation(wyvern:getID(), action:getAnimation(target:getID()))\n            action:messageID(wyvern:getID(), xi.msg.basic.SELF_HEAL_SECONDARY)\n            action:param(wyvern:getID(), totalWyvernHPRestored)\n        end\n\n        if master:getMod(xi.mod.ENHANCES_STRAFE) > 0 then\n            local strafeTP = master:getMerit(xi.merit.STRAFE_EFFECT) * 50\n            wyvern:addTP(strafeTP) -- add 50 TP per merit with augmented AF2 legs\n        end\n\n        return totalHPRestored\n    end,\n})\n\n-- Elemental Breath: Revert to consume TP on breath usage\n-- Source: https://forum.square-enix.com/ffxi/threads/48564-Sep-16-2015-%28JST%29-Version-Update\nm:addOverrideByEra('xi.job_utils.dragoon.useDamageBreath', {\n    [xi.expansion.ROV] = function(wyvern, target, skill, action, damageType)\n        local result = super(wyvern, target, skill, action, damageType)\n\n        wyvern:setTP(0)\n\n        return result\n    end,\n})\n\nm:addOverrideByEra('xi.job_utils.dragoon.useSpiritLink', {\n    -- Spirit Link: Revert to pre-September 2015 HP cost and heal formula.\n    -- Source: https://forum.square-enix.com/ffxi/threads/48564-Sep-16-2015-%28JST%29-Version-Update\n    -- Formula taken from: https://wiki.ffo.jp/html/1897.html\n    [xi.expansion.ROV] = function(player, target, ability, action)\n        local wyvern      = player:getPet()\n        local playerHP    = player:getHP()\n        local petTP       = wyvern:getTP()\n        local regenAmount = player:getMainLvl() / 3 -- level/3 tic regen\n\n        xi.job_utils.dragoon.checkForRemovableEffectsOnSpiritLink(player, wyvern)\n\n        -- Empathy: copy status effects and grant wyvern EXP\n        xi.job_utils.dragoon.applyEmpathyBonus(player, wyvern)\n\n        wyvern:addStatusEffect(xi.effect.REGEN, { power = regenAmount, duration = 90, origin = player, tick = 3 }) -- 90 seconds of regen\n        player:addTP(petTP / 2) -- add half wyvern tp to you\n        wyvern:delTP(petTP / 2) -- remove half tp from wyvern\n\n        -- Calculate drain amount.\n        local drainamount = 0\n\n        if wyvern:getHP() ~= wyvern:getMaxHP() then\n            drainamount = (math.randomInt(25, 35) / 100) * playerHP\n            drainamount = drainamount * (1 - (0.01 * player:getJobPointLevel(xi.jp.SPIRIT_LINK_EFFECT)))\n        end\n\n        -- Handle Stoneskin.\n        local stoneskinPower = 0\n        local stoneskin      = player:getStatusEffect(xi.effect.STONESKIN)\n        if stoneskin then\n            stoneskinPower = stoneskin:getPower()\n\n            -- If stoneskin is more powerfull than the amount to be drained.\n            if stoneskinPower > drainamount then\n                stoneskin:setPower(stoneskinPower - drainamount) -- Fixes the status effect so when it ends it uses the new power instead of old.\n\n            -- If stoneskin is as powerful or less than the amount to be drained.\n            else\n                player:delStatusEffect(xi.effect.STONESKIN)\n            end\n        end\n\n        -- Handle master damage and pet healing.\n        player:takeDamage(math.max(0, drainamount - stoneskinPower))\n\n        local playerMND = player:getStat(xi.mod.MND)\n        local alpha     = math.floor(wyvern:getMainLvl() * 0.7)\n        local healPet   = (drainamount + playerMND + alpha) * 2\n\n        if xi.equipment.getUsableEquipID(player, xi.slot.HEAD) == xi.item.DRACHEN_ARMET_P1 then\n            healPet = healPet + 10\n        end\n\n        -- Spirit Link is self target but reports effect on Wyvern.\n        action:ID(player:getID(), wyvern:getID())\n\n        return wyvern:addHP(healPet) -- add the hp to wyvern\n    end,\n\n    -- Spirit Link: Revert TP transfer from wyvern to master, regen, and doubled heal\n    -- TP Transfer Source: https://www.bg-wiki.com/ffxi/Version_Update_(06/21/2010)\n    -- Heal Doubling Source: https://forum.square-enix.com/ffxi/threads/20744\n    -- Regen Source: https://www.bg-wiki.com/ffxi/Version_Update_(03/26/2012)\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local wyvern      = player:getPet()\n        local playerHP    = player:getHP()\n\n        xi.job_utils.dragoon.checkForRemovableEffectsOnSpiritLink(player, wyvern)\n\n        -- Empathy: copy status effects and grant wyvern EXP\n        xi.job_utils.dragoon.applyEmpathyBonus(player, wyvern)\n\n        -- Pre-Abyssea: No TP transfer from wyvern to master\n\n        -- Calculate drain amount.\n        local drainAmount = 0\n\n        if wyvern:getHP() ~= wyvern:getMaxHP() then\n            drainAmount = (math.randomInt(25, 35) / 100) * playerHP\n            drainAmount = drainAmount * (1 - (0.01 * player:getJobPointLevel(xi.jp.SPIRIT_LINK_EFFECT)))\n        end\n\n        -- Handle Stoneskin.\n        local stoneskinPower = 0\n        local stoneskin      = player:getStatusEffect(xi.effect.STONESKIN)\n        if stoneskin then\n            stoneskinPower = stoneskin:getPower()\n\n            -- If stoneskin is more powerfull than the amount to be drained.\n            if stoneskinPower > drainAmount then\n                stoneskin:setPower(stoneskinPower - drainAmount) -- Fixes the status effect so when it ends it uses the new power instead of old.\n\n            -- If stoneskin is as powerful or less than the amount to be drained.\n            else\n                player:delStatusEffect(xi.effect.STONESKIN)\n            end\n        end\n\n        -- Handle master damage and pet healing.\n        player:takeDamage(math.max(0, drainAmount - stoneskinPower))\n\n        -- Pre-February 2012: Heal is not doubled.\n        -- Source: https://wiki.ffo.jp/html/1897.html\n        local playerMND = player:getStat(xi.mod.MND)\n        local alpha     = math.floor(wyvern:getMainLvl() * 0.7)\n        local healPet   = drainAmount + playerMND + alpha\n\n        if xi.equipment.getUsableEquipID(player, xi.slot.HEAD) == xi.item.DRACHEN_ARMET_P1 then\n            healPet = healPet + 10\n        end\n\n        -- Spirit Link is self target but reports effect on Wyvern.\n        action:ID(player:getID(), wyvern:getID())\n\n        return wyvern:addHP(healPet) -- add the hp to wyvern\n    end,\n})\n\nm:addOverrideByEra('xi.job_utils.dragoon.addWyvernExp', {\n    -- Wyvern EXP: Revert WS Damage bonus from wyvern level-ups\n    -- Source: https://forum.square-enix.com/ffxi/threads/55997-October.-10-2019-%28JST%29-Version-Update\n    [xi.expansion.ROV] = function(player, exp)\n        local wyvern      = player:getPet()\n        local prevExp     = wyvern:getLocalVar('wyvern_exp')\n        local numLevelUps = 0\n\n        if prevExp < 1000 then\n            local currentExp = exp\n            if prevExp + currentExp > 1000 then\n                currentExp = 1000 - prevExp\n            end\n\n            numLevelUps = math.floor((prevExp + currentExp) / 200) - math.floor(prevExp / 200)\n\n            if numLevelUps ~= 0 then\n                local wyvernAttributeIncreaseEffectJP = player:getJobPointLevel(xi.jp.WYVERN_ATTR_BONUS)\n                local wyvernBonusDA = player:getMod(xi.mod.WYVERN_ATTRIBUTE_DA)\n\n                wyvern:addMod(xi.mod.ACC, 6 * numLevelUps)\n                wyvern:addMod(xi.mod.HPP, 6 * numLevelUps)\n                wyvern:addMod(xi.mod.ATTP, 5 * numLevelUps)\n\n                wyvern:updateHealth()\n                wyvern:setHP(wyvern:getMaxHP())\n\n                player:messageBasic(xi.msg.basic.STATUS_INCREASED, 0, 0, wyvern)\n\n                player:addMod(xi.mod.ATT, wyvernAttributeIncreaseEffectJP * numLevelUps)\n                player:addMod(xi.mod.DEF, wyvernAttributeIncreaseEffectJP * numLevelUps)\n                player:addMod(xi.mod.ATTP, 4 * numLevelUps)\n                player:addMod(xi.mod.DEFP, 4 * numLevelUps)\n                player:addMod(xi.mod.HASTE_ABILITY, 200 * numLevelUps)\n                player:addMod(xi.mod.DOUBLE_ATTACK, wyvernBonusDA * numLevelUps)\n            end\n\n            wyvern:setLocalVar('wyvern_exp', prevExp + exp)\n            wyvern:setLocalVar('level_Ups', wyvern:getLocalVar('level_Ups') + numLevelUps)\n        end\n\n        return numLevelUps\n    end,\n\n    -- Wyvern Levelup: Remove player stat transfers from wyvern levelups\n    -- Source: https://www.bg-wiki.com/ffxi/Version_Update_(04/29/2013)\n    [xi.expansion.SOA] = function(player, exp)\n        local wyvern      = player:getPet()\n        local prevExp     = wyvern:getLocalVar('wyvern_exp')\n        local numLevelUps = 0\n\n        if prevExp < 1000 then\n            -- cap exp at 1000 to prevent wyvern leveling up many times from large exp awards\n            local currentExp = exp\n            if prevExp + currentExp > 1000 then\n                currentExp = 1000 - prevExp\n            end\n\n            numLevelUps = math.floor((prevExp + currentExp) / 200) - math.floor(prevExp / 200)\n\n            if numLevelUps ~= 0 then\n                wyvern:addMod(xi.mod.ACC, 6 * numLevelUps)\n                wyvern:addMod(xi.mod.HPP, 6 * numLevelUps)\n                wyvern:addMod(xi.mod.ATTP, 5 * numLevelUps)\n\n                wyvern:updateHealth()\n                wyvern:setHP(wyvern:getMaxHP())\n\n                player:messageBasic(xi.msg.basic.STATUS_INCREASED, 0, 0, wyvern)\n            end\n\n            wyvern:setLocalVar('wyvern_exp', prevExp + exp)\n            wyvern:setLocalVar('level_Ups', wyvern:getLocalVar('level_Ups') + numLevelUps)\n        end\n\n        return numLevelUps\n    end,\n\n    -- Wyvern: Revert experience points Wyvern system\n    -- Source: https://www.bg-wiki.com/ffxi/Version_Update_(03/11/2008)\n    [xi.expansion.WOTG] = function(player, exp)\n        return 0\n    end,\n})\n\nm:addOverrideByEra('xi.effects.spirit_surge.onEffectGain', {\n    -- Spirit Surge: Removes ATK and DEF bonuses\n    -- Source: https://forum.square-enix.com/ffxi/threads/44090-Sep-9-2014-%28JST%29-Version-Update\n    [xi.expansion.SOA] = function(target, effect)\n        effect:addMod(xi.mod.HP, effect:getPower())\n        target:updateHealth()\n\n        effect:addMod(xi.mod.STR, effect:getSubPower())\n        effect:addMod(xi.mod.ACC, 50)\n        effect:addMod(xi.mod.HASTE_ABILITY, 2500)\n        effect:addMod(xi.mod.MAIN_DMG_RATING, target:getJobPointLevel(xi.jp.SPIRIT_SURGE_EFFECT))\n    end,\n\n    -- Spirit Surge: Revert haste to be HASTE_MAGIC instead of HASTE_ABILITY\n    -- Also removes ATK and DEF bonuses which are removed in SoA case\n    -- Source: https://www.bg-wiki.com/ffxi/Version_Update_(02/13/2012)\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        effect:addMod(xi.mod.HP, effect:getPower())\n        target:updateHealth()\n\n        effect:addMod(xi.mod.STR, effect:getSubPower())\n        effect:addMod(xi.mod.ACC, 50)\n        effect:addMod(xi.mod.HASTE_MAGIC, 2500)\n        effect:addMod(xi.mod.MAIN_DMG_RATING, target:getJobPointLevel(xi.jp.SPIRIT_SURGE_EFFECT))\n    end,\n})\n\n-- Ancient Circle: Revert duration from 3 minutes to 1 minute\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(02/13/2012)\nm:addOverrideByEra('xi.job_utils.dragoon.useAncientCircle', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability)\n        local duration = 60 + player:getMod(xi.mod.ANCIENT_CIRCLE_DURATION)\n        local power    = 15\n\n        if player:getMainJob() ~= xi.job.DRG then\n            power = 5\n        end\n\n        power = power + player:getMod(xi.mod.ANCIENT_CIRCLE_POTENCY)\n\n        ability:setMsg(xi.msg.basic.USES_ABILITY_FORTIFIED_DRAGONS)\n\n        target:addStatusEffect(xi.effect.ANCIENT_CIRCLE, { power = power, duration = duration, origin = player })\n\n        return xi.effect.ANCIENT_CIRCLE\n    end,\n})\n\n-- Spirit Surge + Super Jump: Revert enmity reduction from 100% to 50%\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(03/26/2012)\nm:addOverrideByEra('xi.job_utils.dragoon.superJumpSurgeEffect', {\n    [xi.expansion.ABYSSEA] = function(player, target)\n        if player:hasStatusEffect(xi.effect.SPIRIT_SURGE) then\n            local minDistance = 9999\n            local closestPartyMember = nil\n\n            -- Find the closest party member\n            local party = player:getPartyWithTrusts()\n            for _, member in pairs(party) do\n                local distance = member:checkDistance(player)\n                if\n                    member:getID() ~= player:getID() and\n                    not member:isDead() and\n                    (distance < minDistance or closestPartyMember == nil)\n                then\n                    closestPartyMember = member\n                    minDistance = distance\n                end\n            end\n\n            -- TODO: verify conditions for how close the dragoon needs to be to the mob, if at all\n            if\n                closestPartyMember and\n                closestPartyMember:isBehind(player) and\n                (player:checkDistance(target) < closestPartyMember:checkDistance(target))\n            then\n                if target:isMob() then\n                    target:lowerEnmity(closestPartyMember, 50)\n                end\n            end\n        end\n    end,\n})\n\n-- Deep Breathing: Apply merit recast reduction instead of breath power bonus\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(03/26/2012)\nm:addOverrideByEra('xi.job_utils.dragoon.useDeepBreathing', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.DEEP_BREATHING) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        local wyvern = player:getPet()\n\n        if wyvern and wyvern:getPetID() == xi.petId.WYVERN then\n            wyvern:addStatusEffect(xi.effect.MAGIC_ATK_BOOST, { duration = 180, origin = player })\n        end\n    end,\n})\n\n-- Deep Breathing Bonus: Remove merit scaling, use flat base bonus only\nm:addOverrideByEra('xi.job_utils.dragoon.getDeepBreathingBonus', {\n    [xi.expansion.ABYSSEA] = function(wyvern, master, isHealing)\n        local bonus = 0\n        local hadEffect = wyvern:hasStatusEffect(xi.effect.MAGIC_ATK_BOOST)\n\n        if hadEffect then\n            bonus = isHealing and 37.5 or 0.75\n\n            wyvern:delStatusEffect(xi.effect.MAGIC_ATK_BOOST)\n        end\n\n        return bonus\n    end,\n})\n\n-- Empathy: Revert Spirit Link granting wyvern 200 EXP per Empathy merit level\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(05/15/2012)\nm:addOverrideByEra('xi.job_utils.dragoon.applyEmpathyBonus', {\n    [xi.expansion.ABYSSEA] = function(player, wyvern)\n        local empathyTotal = player:getMerit(xi.merit.EMPATHY)\n\n        if empathyTotal > 0 then\n            local validEffects = {}\n            local i            = 0\n            local effects      = player:getStatusEffects()\n            local copyi        = 0\n\n            for _, effect in pairs(effects) do\n                if effect:hasEffectFlag(xi.effectFlag.EMPATHY) then\n                    validEffects[i + 1] = effect\n                    i = i + 1\n                end\n            end\n\n            if i < empathyTotal then\n                empathyTotal = i\n            elseif i > empathyTotal then\n                validEffects = xi.job_utils.dragoon.cutEmpathyEffectTable(validEffects, i, empathyTotal)\n            end\n\n            local copyEffect = nil\n            while copyi < empathyTotal do\n                copyEffect = validEffects[copyi + 1]\n                if wyvern:hasStatusEffect(copyEffect:getEffectType()) then\n                    wyvern:delStatusEffectSilent(copyEffect:getEffectType())\n                end\n\n                wyvern:copyStatusEffect(copyEffect)\n                copyi = copyi + 1\n            end\n        end\n    end,\n})\n"},["modules/era/lua/globals/job_utils/monk.lua"]={["Path"]="modules/era/lua/globals/job_utils/monk.lua",["SHA256"]="2ff1ac344bb4b60e99a6f293b1d41260ca2c3e8651118830cc58b1b7a9a7f1f7",["Text"]="-----------------------------------\n-- Module: Monk Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_monk', xi.pre(xi.expansion.ROV))\n\n-- Focus: Revert to flat +20 ACC only\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.effects.focus.onEffectGain', function(target, effect)\n    local bonusPower = effect:getPower()\n\n    effect:addMod(xi.mod.ACC, 20 + bonusPower)\nend)\n\n-- Dodge: Revert to flat +20 EVA only\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.effects.dodge.onEffectGain', function(target, effect)\n    local bonusPower = effect:getPower()\n\n    effect:addMod(xi.mod.EVA, 20 + bonusPower)\nend)\n\n-- Focus: Revert duration from 30 to 120 seconds\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.monk.useFocus', function(player, target, ability)\n    local focusMod = target:getMod(xi.mod.FOCUS_EFFECT)\n    player:addStatusEffect(xi.effect.FOCUS, { power = focusMod, duration = 120, origin = player })\n\n    return xi.effect.FOCUS\nend)\n\n-- Dodge: Revert duration from 30 to 120 seconds\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.monk.useDodge', function(player, target, ability)\n    local dodgeMod = target:getMod(xi.mod.DODGE_EFFECT)\n    player:addStatusEffect(xi.effect.DODGE, { power = dodgeMod, duration = 120, origin = player })\n\n    return xi.effect.DODGE\nend)\n\n-- Chakra: Revert to VIT * 2 healing only\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.monk.useChakra', function(player, target, ability)\n    local chakraRemoval = player:getMod(xi.mod.CHAKRA_REMOVAL)\n\n    -- Status effect removal (unchanged)\n    local chakraStatusEffects =\n    {\n        POISON    = 0,    -- Removed by default\n        BLINDNESS = 0,    -- Removed by default\n        PARALYSIS = 1,\n        DISEASE   = 2,\n        PLAGUE    = 4,\n    }\n\n    for k, v in pairs(chakraStatusEffects) do\n        if bit.band(chakraRemoval, v) == v then\n            player:delStatusEffect(xi.effect[k])\n        end\n    end\n\n    local chakraMultiplier  = 1 + player:getMod(xi.mod.CHAKRA_MULT) / 100\n    local maxRecoveryAmount = (player:getStat(xi.mod.VIT) * 2) * chakraMultiplier\n    local recoveryAmount    = math.min(player:getMaxHP() - player:getHP(), maxRecoveryAmount)\n\n    player:setHP(player:getHP() + recoveryAmount)\n\n    local merits = player:getMerit(xi.merit.INVIGORATE)\n    if merits > 0 then\n        if player:hasStatusEffect(xi.effect.REGEN) then\n            player:delStatusEffect(xi.effect.REGEN)\n        end\n\n        player:addStatusEffect(xi.effect.REGEN, { power = 10, duration = merits, origin = player, tier = 1 })\n    end\n\n    return recoveryAmount\nend)\n\n-- Revert Footwork to original June 2008 implementation\n-- Source: https://wiki.ffo.jp/html/15342.html\n-- TODO:\n--   Normal attacks replaced with kicks only\n--   Max attacks per round capped at 2\n--   Special subtle blow that calculates enemy TP gain as if Monk's delay is 240\n--   Hundred Fists disables Store TP and Attack bonuses from Footwork\n-- m:addOverride('xi.job_utils.monk.useFootwork', function(player, target, ability)\n--     -- Pre-RoV: base kick damage of 20 only, no weapon damage added\n--     local kickDmg        = 20\n--     local kickAttPercent = 25 + player:getMod(xi.mod.FOOTWORK_ATT_BONUS)\n\n--     -- Duration changed from 60 seconds to 300 seconds (5 minutes)\n--     player:addStatusEffect(xi.effect.FOOTWORK, { power = kickDmg, duration = 300, origin = player, subPower = kickAttPercent })\n\n--     return xi.effect.FOOTWORK\n-- end)\n\n-- m:addOverride('xi.effects.footwork.onEffectGain', function(target, effect)\n--     -- Kick damage: bare-hand D + 20 (passed as effect power, no weapon damage)\n--     effect:addMod(xi.mod.KICK_DMG, effect:getPower())\n--     effect:addMod(xi.mod.STORETP, 180)\n--     effect:addMod(xi.mod.HASTE_MAGIC, -6000)\n-- end)\n"},["modules/era/lua/globals/job_utils/ninja.lua"]={["Path"]="modules/era/lua/globals/job_utils/ninja.lua",["SHA256"]="7f7203ced6ab94085ebefb02af195966f40b7e8c849493b3dac4dbf58a88ce83",["Text"]="-----------------------------------\n-- Module: Ninja Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_ninja')\n\n-- Yonin: Remove extra enmity bonus from Utsusemi spells and Yonin merits\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.yonin.onEffectGain', {\n    [xi.expansion.ROV] = function(target, effect)\n        effect:addMod(xi.mod.ACC, -effect:getPower())\n        effect:addMod(xi.mod.NINJA_TOOL, effect:getPower())\n        effect:addMod(xi.mod.ENMITY, effect:getPower())\n    end,\n})\n\n-- Sange: Reverts to Utsusemi based barrage style ranged attack\n-- Source: https://forum.square-enix.com/ffxi/threads/44592-Oct-7-2014-%28JST%29-Version-Update\nm:addOverrideByEra('xi.job_utils.ninja.useSange', {\n    [xi.expansion.SOA] = function(player, target, ability, action)\n        local meritReduction = player:getMerit(xi.merit.SANGE) - 150\n        action:setRecast(math.max(0, action:getRecast() - meritReduction))\n\n        -- Apply Sange effect (shadows are consumed when the ranged attack fires)\n        player:addStatusEffect(xi.effect.SANGE, { duration = 60, origin = player })\n\n        return xi.effect.SANGE\n    end,\n})\n\n-- Sange effect: Replace 100% daken with multi-hit ranged mod\nm:addOverrideByEra('xi.effects.sange.onEffectGain', {\n    [xi.expansion.SOA] = function(target, effect)\n        effect:addMod(xi.mod.SANGE_MULTI_HIT, 1)\n    end,\n})\n\n-- Mijin Gakure: Now applies weakness and normal HP gain on raise\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(07/20/2009)\nm:addOverrideByEra('xi.job_utils.ninja.useMijinGakure', {\n    [xi.expansion.WOTG] = function(player, target, ability, action)\n        local dmg = super(player, target, ability, action)\n\n        player:die({ mijin = false })\n\n        return dmg\n    end,\n})\n"},["modules/era/lua/globals/job_utils/paladin.lua"]={["Path"]="modules/era/lua/globals/job_utils/paladin.lua",["SHA256"]="2f2fa89732dee448ff8ec76a48fa81ef8ec584a23262af7fa09781f844f56434",["Text"]="-----------------------------------\n-- Module: Paladin Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_paladin')\n\n-- Rampart: Revert to a defense bonus plus a magic damage barrier for party members\n-- Source: https://forum.square-enix.com/ffxi/threads/56444-February-12-2020-%28JST%29-Version-Update\nm:addOverrideByEra('xi.job_utils.paladin.useRampart', {\n    [xi.expansion.ROV] = function(player, target, ability)\n        local duration = 30 + player:getMod(xi.mod.RAMPART_DURATION)\n        local defense  = math.floor((player:getMainLvl() - 1) / 4 + 5)\n\n        -- Barrier is VIT * (1 + 0.5 * (members buffed - 1))\n        local members = 0\n        for _, member in pairs(player:getPartyWithTrusts()) do\n            if\n                member:isAlive() and\n                player:checkDistance(member) <= ability:getRadius()\n            then\n                members = members + 1\n            end\n        end\n\n        local barrier = math.floor(player:getStat(xi.mod.VIT) * (1 + 0.5 * (members - 1)))\n\n        target:addStatusEffect(xi.effect.RAMPART, { power = barrier, duration = duration, origin = player, subPower = defense })\n\n        return xi.effect.RAMPART\n    end,\n})\n\n-- Rampart: DEF bonus in place of the damage taken reduction, power holds the magic barrier\nm:addOverrideByEra('xi.effects.rampart.onEffectGain', {\n    [xi.expansion.ROV] = function(target, effect)\n        effect:addMod(xi.mod.DEF, effect:getSubPower())\n\n        if target:isPC() and target:hasTrait(xi.trait.IRON_WILL) then\n            effect:addMod(xi.mod.SPELLINTERRUPT, target:getMerit(xi.merit.IRON_WILL))\n\n            if target:getMod(xi.mod.ENHANCES_IRON_WILL) > 0 then\n                effect:addMod(xi.mod.FASTCAST, target:getMod(xi.mod.ENHANCES_IRON_WILL) * target:getMerit(xi.merit.IRON_WILL) / 19)\n            end\n        end\n    end,\n})\n\n-- Remove rampart barrier prior to stoneskin\nm:addOverrideByEra('utils.handleStoneskin', {\n    [xi.expansion.ROV] = function(actor, damage, attackType)\n        if\n            damage > 0 and\n            attackType == xi.attackType.MAGICAL\n        then\n            local rampart = actor:getStatusEffect(xi.effect.RAMPART)\n            if rampart and rampart:getPower() > 0 then\n                local absorbed = math.min(rampart:getPower(), damage)\n\n                rampart:setPower(rampart:getPower() - absorbed)\n                damage = damage - absorbed\n            end\n        end\n\n        return super(actor, damage, attackType)\n    end,\n})\n\n-- Holy Circle: Revert duration from 3 minutes to 1 minute\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(02/13/2012)\nm:addOverrideByEra('xi.job_utils.paladin.useHolyCircle', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability)\n        local duration = 60 + player:getMod(xi.mod.HOLY_CIRCLE_DURATION)\n        local power    = 15\n\n        if player:getMainJob() ~= xi.job.PLD then\n            power = 5\n        end\n\n        power = power + player:getMod(xi.mod.HOLY_CIRCLE_POTENCY)\n\n        target:addStatusEffect(xi.effect.HOLY_CIRCLE, { power = power, duration = duration, origin = player })\n\n        return xi.effect.HOLY_CIRCLE\n    end,\n})\n\n-- Chivalry: Remove increased MP bonus from merits and reduces cooldown per merit\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.paladin.useChivalry', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.CHIVALRY) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        local tp     = target:getTP()\n        local base   = 0.05 + (player:getMod(xi.mod.ENHANCES_CHIVALRY) / 100)\n        -- MP gained = (TP * 0.05) + (0.0015 * TP * MND)\n        local amount = (tp * base) + (0.0015 * tp * target:getStat(xi.mod.MND))\n\n        target:setTP(0)\n\n        return target:addMP(amount)\n    end,\n})\n\n-- Fealty: Remove duration increase per merit and reduces cooldown per merit\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.paladin.useFealty', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.FEALTY) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        -- Divide by merit value (150s in pre-Abyssea) to recover merit rank count for gear scaling\n        local enhFealty = (player:getMerit(xi.merit.FEALTY) / 150) * player:getMod(xi.mod.ENHANCES_FEALTY)\n        local duration  = 60 + enhFealty\n\n        player:addStatusEffect(xi.effect.FEALTY, { power = 1, duration = duration, origin = player })\n\n        return xi.effect.FEALTY\n    end,\n})\n\n-- Shield Bash: Remove shield size damage bonuses and job point additions\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.paladin.useShieldBash', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability)\n        local damage = math.floor(player:getMainLvl() * 0.28)\n\n        -- Main job factors\n        if player:getMainJob() ~= xi.job.PLD then\n            damage = math.floor(damage / 2.5)\n        else\n            damage = math.floor(damage)\n        end\n\n        damage = damage + player:getMod(xi.mod.SHIELD_BASH)\n\n        -- Apply stun effect\n        if\n            not xi.data.statusEffect.isTargetImmune(target, xi.effect.STUN, xi.element.THUNDER) and\n            not xi.data.statusEffect.isTargetResistant(player, target, xi.effect.STUN) and\n            not xi.data.statusEffect.isEffectNullified(target, xi.effect.STUN, 0)\n        then\n            local maccParams =\n            {\n                effectId       = xi.effect.STUN,\n                magicalElement = xi.element.THUNDER,\n                skillRank      = xi.skillRank.A_PLUS,\n                actorStat      = xi.mod.INT,\n            }\n\n            local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n            if xi.data.statusEffect.isResistRateSuccessfull(xi.effect.STUN, resistanceRate, 0) then\n                target:addStatusEffect(xi.effect.STUN, { power = 1, duration = math.randomInt(2, 8) * resistanceRate, origin = player })\n            end\n        end\n\n        -- Randomize damage\n        local randomizer = 1 + (math.randomInt(1, 5) / 100)\n\n        damage = damage * randomizer\n        damage = utils.handleStoneskin(target, damage)\n\n        target:takeDamage(damage, player, xi.attackType.PHYSICAL, xi.damageType.BLUNT)\n        target:updateEnmityFromDamage(player, damage)\n        ability:setMsg(xi.msg.basic.JA_DAMAGE)\n\n        return damage\n    end,\n})\n"},["modules/era/lua/globals/job_utils/puppetmaster.lua"]={["Path"]="modules/era/lua/globals/job_utils/puppetmaster.lua",["SHA256"]="4ce0f758ae6095ba47b917f63d16d66779ed5fda7054f6c2b05a35edc332a662",["Text"]="-----------------------------------\n-- Module: Puppetmaster Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_puppetmaster', xi.pre(xi.expansion.ABYSSEA))\n\n-- Overdrive: Revert duration from 180 to 60 seconds : https://wiki.ffo.jp/html/954.html\nm:addOverride('xi.job_utils.puppetmaster.onAbilityUseOverdrive', function(player, target, ability, action)\n    local pet = player:getPet()\n\n    player:addStatusEffect(xi.effect.OVERDRIVE, { duration = 60 + player:getMod(xi.mod.OVERDRIVE_BONUS_DURATION), origin = player })\n\n    if pet then\n        pet:addStatusEffect(xi.effect.OVERDRIVE, { duration = 60 + player:getMod(xi.mod.OVERDRIVE_BONUS_DURATION), origin = pet })\n        action:ID(player:getID(), pet:getID())\n    end\n\n    return xi.effect.OVERDRIVE\nend)\n\n-- Repair: Revert recast to a flat 180 seconds : https://wiki.ffo.jp/html/954.html\nm:addOverride('xi.job_utils.puppetmaster.onAbilityCheckRepair', function(player, target, ability)\n    local msg, param = super(player, target, ability)\n\n    if msg == 0 then\n        ability:setRecast(180)\n    end\n\n    return msg, param\nend)\n\nlocal removableEffects =\n{\n    -- Songs\n    xi.effect.ELEGY,\n    xi.effect.REQUIEM,\n    xi.effect.THRENODY,\n\n    -- Enfeebling\n    xi.effect.BLINDNESS,\n    xi.effect.PARALYSIS,\n    xi.effect.SILENCE,\n    xi.effect.CURSE_I,\n    xi.effect.CURSE_II,\n    xi.effect.DISEASE,\n    xi.effect.PLAGUE,\n    xi.effect.WEIGHT,\n    xi.effect.BIND,\n    xi.effect.ADDLE,\n    xi.effect.SLOW,\n    xi.effect.PETRIFICATION,\n\n    -- DoTs\n    xi.effect.BIO,\n    xi.effect.DIA,\n    xi.effect.POISON,\n    xi.effect.BURN,\n    xi.effect.FROST,\n    xi.effect.CHOKE,\n    xi.effect.RASP,\n    xi.effect.SHOCK,\n    xi.effect.DROWN,\n\n    -- Main Stat Downs\n    xi.effect.STR_DOWN,\n    xi.effect.DEX_DOWN,\n    xi.effect.VIT_DOWN,\n    xi.effect.AGI_DOWN,\n    xi.effect.INT_DOWN,\n    xi.effect.MND_DOWN,\n    xi.effect.CHR_DOWN,\n\n    -- Combat Stat Downs\n    xi.effect.ACCURACY_DOWN,\n    xi.effect.ATTACK_DOWN,\n    xi.effect.EVASION_DOWN,\n    xi.effect.DEFENSE_DOWN,\n\n    -- Magic Stat Downs\n    xi.effect.MAGIC_ACC_DOWN,\n    xi.effect.MAGIC_ATK_DOWN,\n    xi.effect.MAGIC_EVASION_DOWN,\n    xi.effect.MAGIC_DEF_DOWN,\n\n    -- HP/MP/TP Stat Downs\n    xi.effect.MAX_TP_DOWN,\n    xi.effect.MAX_MP_DOWN,\n    xi.effect.MAX_HP_DOWN\n}\n\nlocal function removeStatusEffects(pet, amountToRemove)\n    local effectsRemoved = 0\n\n    for _, effectId in ipairs(removableEffects) do\n        if effectsRemoved >= amountToRemove then\n            break\n        end\n\n        if pet:delStatusEffect(effectId) then\n            effectsRemoved = effectsRemoved + 1\n        end\n    end\n\n    return effectsRemoved\nend\n\n-- Before the June 2015 update, oils restored half as much HP per tick for twice as long.\n-- https://forum.square-enix.com/ffxi/threads/47481-Jun-25-2015-%28JST%29-Version-Update\nlocal oilData =\n{\n    [xi.item.CAN_OF_AUTOMATON_OIL   ] = { regen = 10, duration =  30 },\n    [xi.item.CAN_OF_AUTOMATON_OIL_P1] = { regen = 20, duration =  60 },\n    [xi.item.CAN_OF_AUTOMATON_OIL_P2] = { regen = 30, duration =  90 },\n    [xi.item.CAN_OF_AUTOMATON_OIL_P3] = { regen = 40, duration = 120 },\n}\n\n-- Repair: Remove the initial burst heal, leaving only the Regen and status removal effects\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.puppetmaster.onAbilityUseRepair', function(player, target, ability, action)\n    local pet = player:getPet()\n    if not pet then\n        return\n    end\n\n    -- Self-cast ability but reports on pet\n    action:ID(player:getID(), pet:getID())\n\n    local oilEquipped = oilData[player:getEquipID(xi.slot.AMMO)]\n    local regenAmount = oilEquipped.regen\n    local regenTime   = oilEquipped.duration\n\n    removeStatusEffects(pet, player:getMod(xi.mod.REPAIR_EFFECT))\n\n    local bonus = 1 + player:getMod(xi.mod.REPAIR_POTENCY) / 100\n    regenAmount = regenAmount * bonus\n\n    pet:wakeUp()\n\n    pet:delStatusEffect(xi.effect.REGEN)\n    pet:addStatusEffect(xi.effect.REGEN, { power = regenAmount, duration = regenTime, origin = player, tick = 3 }) -- 3 = tick, each 3 seconds.\n    player:removeAmmo(1)\n\n    ability:setMsg(xi.msg.basic.USES_JA)\nend)\n"},["modules/era/lua/globals/job_utils/ranger.lua"]={["Path"]="modules/era/lua/globals/job_utils/ranger.lua",["SHA256"]="a229e61c5c1b1c7c8a2fd2cc9bbe34fe0a51b1eac863d199432d9abbe20b4754",["Text"]="-----------------------------------\n-- Module: Ranger Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_ranger')\n\nlocal function useEagleEyeShot(player, target, action, enmityMult)\n    if player:getWeaponSkillType(xi.slot.RANGED) == xi.skill.MARKSMANSHIP then\n        action:setAnimation(target:getID(), action:getAnimation(target:getID()) + 1)\n    end\n\n    local params = {}\n\n    params.numHits = 1\n\n    -- TP params.\n    local tp          = 1000 -- to ensure ftp multiplier is applied\n    params.ftpMod     = { 5.0, 5.0, 5.0 }\n    params.critVaries = { 0.0, 0.0, 0.0 }\n\n    -- Stat params.\n    params.str_wsc = 0\n    params.dex_wsc = 0\n    params.vit_wsc = 0\n    params.agi_wsc = 0\n    params.int_wsc = 0\n    params.mnd_wsc = 0\n    params.chr_wsc = 0\n\n    params.enmityMult = enmityMult\n\n    -- Job Point Bonus Damage\n    local jpValue = player:getJobPointLevel(xi.jp.EAGLE_EYE_SHOT_EFFECT)\n    player:addMod(xi.mod.ALL_WSDMG_ALL_HITS, jpValue * 3)\n\n    local damage, _, tpHits, extraHits = xi.weaponskills.doRangedWeaponskill(player, target, 0, params, tp, action, true)\n\n    -- Set the message id ourselves\n    if tpHits + extraHits > 0 then\n        action:messageID(target:getID(), xi.msg.basic.JA_DAMAGE)\n    else\n        action:messageID(target:getID(), xi.msg.basic.JA_MISS_2)\n    end\n\n    return damage\nend\n\nm:addOverrideByEra('xi.job_utils.ranger.useEagleEyeShot', {\n    -- Revert shadow bypass\n    -- Source: https://forum.square-enix.com/ffxi/threads/47481-Jun-25-2015-%28JST%29-Version-Update\n    [xi.expansion.ROV] = function(player, target, ability, action)\n        return useEagleEyeShot(player, target, action, 0.5)\n    end,\n\n    -- Revert enmity reduction\n    -- Source: https://www.bg-wiki.com/ffxi/Version_Update_(05/15/2012)\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        return useEagleEyeShot(player, target, action, 1)\n    end,\n})\n\nlocal scavengeData = require('modules/era/lua/data/scavenge_data')\n\n-- Scavenge: Revert to pre-SoA zone-based item gathering and reduce duration with merits\n-- Sources: https://ffxiclopedia.fandom.com/wiki/Scavenge/Items, https://wiki.ffo.jp/html/2985.html\nm:addOverrideByEra('xi.job_utils.ranger.useScavenge', {\n    [xi.expansion.SOA] = function(player, target, ability, action)\n        local meritReduction = player:getMerit(xi.merit.SCAVENGE_EFFECT)\n        action:setRecast(math.max(0, action:getRecast() - meritReduction))\n\n        -- RNG AF2 quest check\n        if xi.job_utils.ranger.tryScavengeQuestItem(player) then\n            return 0\n        end\n\n        local playerID = target:getID()\n        local zoneID   = player:getZoneID()\n        local zoneData = scavengeData.zonePoolMap[zoneID]\n\n        -- Zone has no scavenge pool, return nothing\n        if not zoneData then\n            action:messageID(playerID, xi.msg.basic.SCAVENGE_FIND_NOTHING)\n\n            return 0\n        end\n\n        -- Anti-camping check: must move at least 2 yalms from last Scavenge position\n        local curX  = math.floor(player:getXPos())\n        local curZ  = math.floor(player:getZPos())\n        local lastX = player:getLocalVar('[Scavenge]LastX')\n        local lastZ = player:getLocalVar('[Scavenge]LastZ')\n        player:setLocalVar('[Scavenge]LastX', curX)\n        player:setLocalVar('[Scavenge]LastZ', curZ)\n\n        if lastX > 0 then\n            local lastPos = { x = lastX, y = 0, z = lastZ }\n            local curPos  = { x = curX,  y = 0, z = curZ }\n\n            if utils.distanceWithin(lastPos, curPos, 2, true) then\n                action:messageID(playerID, xi.msg.basic.SCAVENGE_FIND_NOTHING)\n\n                return 0\n            end\n        end\n\n        -- Success rate check\n        if math.randomInt(1, 100) > 25 + player:getMod(xi.mod.SCAVENGE_EFFECT) then\n            action:messageID(playerID, xi.msg.basic.SCAVENGE_FIND_NOTHING)\n\n            return 0\n        end\n\n        -- Build the item pool for scavenge rewards with common items + zone specific items + that zones ammo tier.\n        local itemPool = {}\n        local supplies = {}\n\n        for _, v in pairs(zoneData.scavengePool) do\n            itemPool[#itemPool + 1] = v\n        end\n\n        for _, itemID in ipairs(scavengeData.commonItems) do\n            supplies[#supplies + 1] = itemID\n        end\n\n        for _, itemID in ipairs(zoneData.ammoPool) do\n            supplies[#supplies + 1] = itemID\n        end\n\n        itemPool[#itemPool + 1] = supplies[math.randomInt(1, #supplies)]\n\n        local selectedItem = itemPool[math.randomInt(1, #itemPool)]\n\n        if player:addItem(selectedItem) then\n            action:messageID(playerID, xi.msg.basic.SCAVENGE_FIND_ITEM)\n\n            return selectedItem\n        end\n\n        action:messageID(playerID, xi.msg.basic.SCAVENGE_FIND_NOTHING)\n\n        return 0\n    end,\n})\n\n-- Flashy Shot: Apply merit recast reduction\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.job_utils.ranger.useFlashyShot', {\n    [xi.expansion.ABYSSEA] = function(player, target, ability, action)\n        local recastReduction = player:getMerit(xi.merit.FLASHY_SHOT) - 150\n        action:setRecast(action:getRecast() - recastReduction)\n\n        player:addStatusEffect(xi.effect.FLASHY_SHOT, { power = 1, duration = 60, origin = player })\n\n        return xi.effect.FLASHY_SHOT\n    end,\n})\n\n-- Flashy Shot Effect: Add level correction bypass\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.flashy_shot.onEffectGain', {\n    [xi.expansion.ABYSSEA] = function(target, effect)\n        effect:addMod(xi.mod.ENMITY, 50)\n        effect:addMod(xi.mod.RA_IGNORE_LVL_DIFF, 1)\n    end,\n})\n\n-- Camouflage: Remove reduced enmity and chance to retain after ranged attack\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.camouflage.onEffectGain', {\n    [xi.expansion.WOTG] = function(target, effect)\n    end,\n})\n\n-- Unlimited Shot: In WotG era, removed on any ranged attack, not just successful hits\n-- TODO: find a patch note or source for this change\nm:addOverrideByEra('xi.effects.unlimited_shot.onEffectGain', {\n    [xi.expansion.WOTG] = function(target, effect)\n    end,\n})\n"},["modules/era/lua/globals/job_utils/samurai.lua"]={["Path"]="modules/era/lua/globals/job_utils/samurai.lua",["SHA256"]="36bb55b22787c9a3fab71be57197cc7580af1b6d787c17860fda83fbb4b9f159",["Text"]="-----------------------------------\n-- Module: Samurai Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_samurai', xi.pre(xi.expansion.ABYSSEA))\n\n-- Warding Circle: Revert duration from 3 minutes to 1 minute\n-- Source: https://www.bg-wiki.com/ffxi/Version_Update_(02/13/2012)\nm:addOverride('xi.job_utils.samurai.useWardingCircle', function(player, target, ability)\n    local duration = 60 + player:getMod(xi.mod.WARDING_CIRCLE_DURATION)\n    local power    = 15\n\n    if player:getMainJob() ~= xi.job.SAM then\n        power = 5\n    end\n\n    power = power + player:getMod(xi.mod.WARDING_CIRCLE_POTENCY)\n\n    target:addStatusEffect(xi.effect.WARDING_CIRCLE, { power = power, duration = duration, origin = player })\n\n    return xi.effect.WARDING_CIRCLE\nend)\n\n-- Blade Bash: Apply merit recast reduction, remove extra plague duration from merits\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.samurai.useBladeBash', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.BLADE_BASH) - 150\n    action:setRecast(action:getRecast() - recastReduction)\n\n    -- Damage\n    -- TODO: Verify damage formula and DRK interaction\n    local jobLevel = utils.getActiveJobLevel(player, xi.job.DRK)\n    local damage   = math.floor((jobLevel + 11) / 4 + player:getMod(xi.mod.WEAPON_BASH))\n    damage = utils.handleStoneskin(target, damage)\n    target:takeDamage(damage, player, xi.attackType.PHYSICAL, xi.damageType.BLUNT)\n    target:updateEnmityFromDamage(player, damage)\n\n    -- Stun\n    if\n        not xi.data.statusEffect.isTargetImmune(target, xi.effect.STUN, xi.element.THUNDER) and\n        not xi.data.statusEffect.isTargetResistant(player, target, xi.effect.STUN) and\n        not xi.data.statusEffect.isEffectNullified(target, xi.effect.STUN, 0)\n    then\n        local maccParams =\n        {\n            effectId       = xi.effect.STUN,\n            magicalElement = xi.element.THUNDER,\n            skillRank      = xi.skillRank.A_PLUS,\n            actorStat      = xi.mod.INT,\n        }\n\n        local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n        if xi.data.statusEffect.isResistRateSuccessfull(xi.effect.STUN, resistanceRate, 0) then\n            target:addStatusEffect(xi.effect.STUN, { power = 1, duration = 6 * resistanceRate, origin = player })\n        end\n    end\n\n    -- Plague\n    if\n        not xi.data.statusEffect.isTargetImmune(target, xi.effect.PLAGUE, xi.element.FIRE) and\n        not xi.data.statusEffect.isTargetResistant(player, target, xi.effect.PLAGUE) and\n        not xi.data.statusEffect.isEffectNullified(target, xi.effect.PLAGUE, 0)\n    then\n        local maccParams =\n        {\n            effectId       = xi.effect.PLAGUE,\n            magicalElement = xi.element.FIRE,\n            skillRank      = xi.skillRank.A_PLUS,\n            actorStat      = xi.mod.INT,\n        }\n\n        local resistanceRate = xi.combat.magicHitRate.calculateResistRate(player, target, maccParams)\n        if xi.data.statusEffect.isResistRateSuccessfull(xi.effect.PLAGUE, resistanceRate, 0) then\n            target:addStatusEffect(xi.effect.PLAGUE, { power = 5, duration = 15 * resistanceRate, origin = player })\n        end\n    end\n\n    -- Animation\n    local animationTable =\n    {\n        -- [weapon type] = animation ID\n        [xi.skill.GREAT_SWORD ] = 201,\n        [xi.skill.GREAT_KATANA] = 201,\n        [xi.skill.GREAT_AXE   ] = 202,\n        [xi.skill.SCYTHE      ] = 202,\n        [xi.skill.STAFF       ] = 202,\n        [xi.skill.POLEARM     ] = 203,\n    }\n\n    local animation = animationTable[player:getWeaponSkillType(xi.slot.MAIN)] or 0\n    action:setAnimation(target:getID(), animation)\n\n    ability:setMsg(xi.msg.basic.JA_DAMAGE)\n\n    return damage\nend)\n\n-- Shikikoyo: Apply merit recast reduction, remove extra TP sharing from merits\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.samurai.useShikikoyo', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.SHIKIKOYO) - 150\n    action:setRecast(action:getRecast() - recastReduction)\n\n    local pTP = player:getTP() - 1000\n    pTP       = utils.clamp(pTP, 0, 3000 - target:getTP())\n\n    player:setTP(1000)\n    target:setTP(target:getTP() + pTP)\n\n    return pTP\nend)\n\n-- Hasso: Remove Zanshin bonus\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.effects.hasso.onEffectGain', function(target, effect)\n    effect:addMod(xi.mod.TWOHAND_STR, effect:getPower())\n    effect:addMod(xi.mod.TWOHAND_HASTE_ABILITY, 1000)\n    effect:addMod(xi.mod.TWOHAND_ACC, 10)\nend)\n\n-- Seigan: Remove Zanshin-based counter bonus\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.effects.seigan.onEffectGain', function(target, effect)\n    local jpValue = target:getJobPointLevel(xi.jp.SEIGAN_EFFECT)\n\n    effect:addMod(xi.mod.DEF, jpValue * 3)\nend)\n"},["modules/era/lua/globals/job_utils/summoner.lua"]={["Path"]="modules/era/lua/globals/job_utils/summoner.lua",["SHA256"]="1a85de990d71973dfbfb952bfd6ccf597f923a0f6c3dcbb96cba3a988078afb0",["Text"]="-----------------------------------\n-- Module: Summoner spirit perpetuation cost helpers\n-- The override target does not exist in the base scripts; declaring it here\n-- creates it for the other era modules that call it.\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_summoner')\n\n-- Perpetuation cost breakpoints for elemental spirits, in ascending level order.\n-- Source: https://forum.square-enix.com/ffxi/threads/22099-March-27-2012-%28JST%29-Version-Update\nlocal spiritPerpThresholds =\n{\n    { level =  5, cost =  2 },\n    { level =  9, cost =  3 },\n    { level = 14, cost =  4 },\n    { level = 18, cost =  5 },\n    { level = 23, cost =  6 },\n    { level = 25, cost =  7 },\n    { level = 27, cost =  8 },\n    { level = 32, cost =  9 },\n    { level = 36, cost = 10 },\n    { level = 40, cost = 11 },\n    { level = 45, cost = 12 },\n    { level = 49, cost = 13 },\n    { level = 54, cost = 14 },\n    { level = 58, cost = 15 },\n    { level = 63, cost = 16 },\n    { level = 67, cost = 17 },\n    { level = 72, cost = 18 },\n}\n\nlocal carbunclePerpThresholds =\n{\n    { level = 10, cost =  1 },\n    { level = 18, cost =  2 },\n    { level = 27, cost =  3 },\n    { level = 36, cost =  4 },\n    { level = 45, cost =  5 },\n    { level = 54, cost =  6 },\n    { level = 63, cost =  7 },\n    { level = 72, cost =  8 },\n    { level = 81, cost =  9 },\n    { level = 91, cost = 10 },\n    { level = 92, cost = 11 },\n}\n\nlocal fenrirPerpThresholds =\n{\n    { level =  8, cost =  1 },\n    { level = 15, cost =  2 },\n    { level = 22, cost =  3 },\n    { level = 30, cost =  4 },\n    { level = 37, cost =  5 },\n    { level = 45, cost =  6 },\n    { level = 51, cost =  7 },\n    { level = 59, cost =  8 },\n    { level = 66, cost =  9 },\n    { level = 73, cost = 10 },\n    { level = 81, cost = 11 },\n    { level = 91, cost = 12 },\n    { level = 92, cost = 13 },\n}\n\nlocal avatarPerpThresholds =\n{\n    { level = 10, cost =  3 },\n    { level = 19, cost =  4 },\n    { level = 28, cost =  5 },\n    { level = 38, cost =  6 },\n    { level = 47, cost =  7 },\n    { level = 56, cost =  8 },\n    { level = 65, cost =  9 },\n    { level = 68, cost = 10 },\n    { level = 71, cost = 11 },\n    { level = 74, cost = 12 },\n    { level = 81, cost = 13 },\n    { level = 91, cost = 14 },\n    { level = 92, cost = 15 },\n}\n\nm:addOverrideByEra('xi.job_utils.summoner.getPerpetuationCost', {\n    [xi.expansion.ABYSSEA] = function(pet)\n        local thresholds = {}\n\n        local petId    = pet:getPetID()\n        local petLevel = pet:getMainLvl()\n\n        if petId <= xi.petId.DARK_SPIRIT then\n            thresholds = spiritPerpThresholds\n        elseif\n            petId == xi.petId.CARBUNCLE or\n            petId == xi.petId.CAIT_SITH\n        then\n            thresholds = carbunclePerpThresholds\n        elseif petId == xi.petId.FENRIR then\n            thresholds = fenrirPerpThresholds\n        elseif\n            (petId >= xi.petId.IFRIT and petId <= xi.petId.DIABOLOS) or\n            petId == xi.petId.SIREN\n        then\n            thresholds = avatarPerpThresholds\n        else\n            return 0\n        end\n\n        for _, threshold in ipairs(thresholds) do\n            if petLevel < threshold.level then\n                return threshold.cost\n            end\n        end\n\n        return thresholds[#thresholds].cost\n    end,\n})\n\nm:addOverrideByEra('xi.job_utils.summoner.applyPerpetuationCost', {\n    [xi.expansion.ABYSSEA] = function(caster, pet)\n        local meritReduction = 0\n        local baseCost       = 0\n\n        if pet then\n            local petId = pet:getPetID()\n\n            baseCost = xi.job_utils.summoner.getPerpetuationCost(pet)\n\n            if\n                petId >= xi.petId.FIRE_SPIRIT and\n                petId <= xi.petId.DARK_SPIRIT\n            then\n                -- SUMMONING_MAGIC_CAST_TIME used to be Elemental MP Cost catagory which reduced spirit perpetuation.\n                -- Elemental MP Cost was removed in March 2012 and replaced with SUMMONING_MAGIC_CAST_TIME.\n                meritReduction = caster:getMerit(xi.merit.SUMMONING_MAGIC_CAST_TIME)\n            end\n\n            caster:setMod(xi.mod.AVATAR_PERPETUATION, math.max(0, baseCost - meritReduction))\n        end\n    end,\n})\n"},["modules/era/lua/globals/job_utils/thief.lua"]={["Path"]="modules/era/lua/globals/job_utils/thief.lua",["SHA256"]="820e43cd6627ce67c7fe2b856139d9ca171d5dfcf99ea76ce365328c5b86693d",["Text"]="-----------------------------------\n-- Module: Thief Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_thief', xi.pre(xi.expansion.ABYSSEA))\n\n-- Assassin's Charge: Remove Quadruple Attack\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.effects.assassins_charge.onEffectGain', function(target, effect)\n    effect:addMod(xi.mod.TRIPLE_ATTACK, 100)\nend)\n\n-- Assassin's Charge: Reduce cooldown by merit count\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.thief.useAssassinsCharge', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.ASSASSINS_CHARGE) - 150\n    action:setRecast(action:getRecast() - recastReduction)\n\n    player:addStatusEffect(xi.effect.ASSASSINS_CHARGE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.ASSASSINS_CHARGE\nend)\n\n-- Feint: Remove Treasure Hunter rate and reduce cooldown by merit count\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.thief.useFeint', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.FEINT) - 120\n    action:setRecast(action:getRecast() - recastReduction)\n\n    player:addStatusEffect(xi.effect.FEINT, { power = 150, duration = 60, origin = player })\nend)\n"},["modules/era/lua/globals/job_utils/warrior.lua"]={["Path"]="modules/era/lua/globals/job_utils/warrior.lua",["SHA256"]="ba9bc9a153c070ca284fa05ea45863bc6d4a83f7264458ae36076085469e3308",["Text"]="-----------------------------------\n-- Module: Warrior Job Adjustments\n-----------------------------------\n-- https://forum.square-enix.com/ffxi/threads/44592-Oct-7-2014-%28JST%29-Version-Update (Berserk and Defender changes)\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_warrior', xi.pre(xi.expansion.ABYSSEA))\n\n-- Remove Level Scaling from Berserk\nm:addOverride('xi.job_utils.warrior.useBerserk', function(player, target, ability)\n    local power    = 25 + player:getMod(xi.mod.BERSERK_POTENCY)\n    local duration = 180 + player:getMod(xi.mod.BERSERK_DURATION)\n\n    player:addStatusEffect(xi.effect.BERSERK, { power = power, duration = duration, origin = player, subPower = 25 })\n\n    return xi.effect.BERSERK\nend)\n\n-- Remove Level Scaling from Defender\nm:addOverride('xi.job_utils.warrior.useDefender', function(player, target, ability)\n    local duration = 180 + player:getMod(xi.mod.DEFENDER_DURATION)\n\n    player:addStatusEffect(xi.effect.DEFENDER, { power = 25, duration = duration, origin = player })\n\n    return xi.effect.DEFENDER\nend)\n\n-- Warrior's Charge: Remove Triple Attack bonus\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.effects.warriors_charge.onEffectGain', function(target, effect)\n    effect:addMod(xi.mod.DOUBLE_ATTACK, 100)\nend)\n\n-- Warrior's Charge: Apply merit recast reduction\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.warrior.useWarriorsCharge', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.WARRIORS_CHARGE) - 150\n    action:setRecast(action:getRecast() - recastReduction)\n\n    player:addStatusEffect(xi.effect.WARRIORS_CHARGE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.WARRIORS_CHARGE\nend)\n"},["modules/era/lua/globals/job_utils/white_mage.lua"]={["Path"]="modules/era/lua/globals/job_utils/white_mage.lua",["SHA256"]="d3dcca42f7cb357b33a26634d9a01e59476b15dbf4dbb0e2bda47e9d89f304e0",["Text"]="-----------------------------------\n-- Module: White Mage Job Adjustments\n-----------------------------------\nrequire('modules/module_utils')\n-----------------------------------\nlocal m = Module:new('era_job_utils_white_mage', xi.pre(xi.expansion.ABYSSEA))\n\n-- Martyr: Apply merit recast reduction, remove merit healing bonus\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.white_mage.useMartyr', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.MARTYR) - 150\n    action:setRecast(action:getRecast() - recastReduction)\n\n    local damageHP = math.floor(player:getHP() * 0.25)\n    local healHP = damageHP * 2\n    healHP = utils.clamp(healHP, 0, target:getMaxHP() - target:getHP())\n\n    -- If stoneskin is present, it should absorb damage\n    damageHP = utils.handleStoneskin(player, damageHP)\n    player:delHP(damageHP)\n    target:addHP(healHP)\n\n    return healHP\nend)\n\n-- Devotion: Apply merit recast reduction, remove merit MP bonus\n-- TODO: find a patch note or source for this change\nm:addOverride('xi.job_utils.white_mage.useDevotion', function(player, target, ability, action)\n    local recastReduction = player:getMerit(xi.merit.DEVOTION) - 150\n    action:setRecast(action:getRecast() - recastReduction)\n\n    local damageHP = math.floor(player:getHP() * 0.25)\n    local healMP = damageHP\n    healMP = utils.clamp(healMP, 0, target:getMaxMP() - target:getMP())\n\n    -- If stoneskin is present, it should absorb damage\n    damageHP = utils.handleStoneskin(player, damageHP)\n    player:delHP(damageHP)\n    target:addMP(healMP)\n\n    return healMP\nend)\n"},["modules/phoenix/lua/globals/gil_audit_sources.lua"]={["Path"]="modules/phoenix/lua/globals/gil_audit_sources.lua",["SHA256"]="397048c8199cba7d7b5430bc6f7ea2527127e482b858f7b5527bc9e3b62f5da5",["Text"]="-----------------------------------\n-- Gil Economy Ledger - Script Sources\n--\n-- The gil_audit C++ module observes every gil balance change but not why it moved.\n-- These overrides declare the reason for the central helpers most scripted gil\n-- funnels through, call super() unchanged, then retire the reason so a helper\n-- that bails without moving gil cannot label a later movement.\n--\n-- Leaf scripts calling player:addGil directly still have their amount recorded,\n-- but land as Unknown rather than Script.\n-----------------------------------\n-- luacheck: globals __gilAuditSetReason __gilAuditRetireReason\nlocal m = Module:new('gil_audit_sources')\n\n-- The module loader replaces a missing override target with an empty function, which would\n-- silently turn the helper into a no-op. Refuse to load instead so an upstream rename is caught at startup.\nlocal function resolve(path)\n    local value = _G\n    for part in string.gmatch(path, '[^.]+') do\n        if type(value) ~= 'table' then\n            return nil\n        end\n\n        value = value[part]\n    end\n\n    return value\nend\n\nlocal overrideTargets =\n{\n    'npcUtil.giveCurrency',\n    'npcUtil.giveReward',\n    'npcUtil.completeQuest',\n    'npcUtil.completeMission',\n    'xi.player.charCreate',\n    'xi.mob.onMobDeathEx',\n    'xi.job_utils.thief.useMug',\n    'xi.rentalChocobo.renterOnEventFinish',\n    'xi.regime.checkRegime',\n    'xi.commands.givegil.onTrigger',\n    'xi.commands.takegil.onTrigger',\n    'xi.commands.setgil.onTrigger',\n}\n\nfor _, path in ipairs(overrideTargets) do\n    if type(resolve(path)) ~= 'function' then\n        error(string.format('gil_audit_sources: override target %s does not exist, refusing to load', path))\n    end\nend\n\n-- Must match the GilSource enum in modules/phoenix/cpp/gil_audit.cpp\nlocal gilSource =\n{\n    MOB_DROP   = 1,\n    SCRIPT     = 12,\n    GM_COMMAND = 13,\n}\n\n-- `player` is whose gil moves, which for !givegil is the target rather than the caller.\n-- Returns whether a reason was pushed, so retire() can pop exactly what was pushed.\n-- No-op when the C++ module is not loaded, and never allowed to break the game action.\nlocal function declare(player, source, detail, counterparty)\n    if not __gilAuditSetReason or not player then\n        return false\n    end\n\n    local ok = pcall(__gilAuditSetReason, player:getID(), source, detail or '', counterparty or 0)\n    return ok\nend\n\nlocal function retire(declared)\n    if declared and __gilAuditRetireReason then\n        pcall(__gilAuditRetireReason)\n    end\nend\n\n-----------------------------------\n-- npcUtil helpers\n-----------------------------------\n\nm:addOverride('npcUtil.giveCurrency', function(player, currency, amount, useTreasurePoolMsg)\n    local declared = false\n    if type(currency) == 'string' and string.lower(currency) == 'gil' then\n        declared = declare(player, gilSource.SCRIPT, 'npcUtil.giveCurrency')\n    end\n\n    local result = super(player, currency, amount, useTreasurePoolMsg)\n    retire(declared)\n\n    return result\nend)\n\nm:addOverride('npcUtil.giveReward', function(player, params)\n    local declared = false\n    if type(params) == 'table' and type(params.gil) == 'number' then\n        declared = declare(player, gilSource.SCRIPT, 'npcUtil.giveReward')\n    end\n\n    local result = super(player, params)\n    retire(declared)\n\n    return result\nend)\n\nm:addOverride('npcUtil.completeQuest', function(player, area, quest, params)\n    local declared = false\n    if type(params) == 'table' and type(params.gil) == 'number' then\n        declared = declare(player, gilSource.SCRIPT, 'npcUtil.completeQuest')\n    end\n\n    local result = super(player, area, quest, params)\n    retire(declared)\n\n    return result\nend)\n\nm:addOverride('npcUtil.completeMission', function(player, logId, missionId, params)\n    local declared = false\n    if type(params) == 'table' and type(params.gil) == 'number' then\n        declared = declare(player, gilSource.SCRIPT, 'npcUtil.completeMission')\n    end\n\n    local result = super(player, logId, missionId, params)\n    retire(declared)\n\n    return result\nend)\n\n-----------------------------------\n-- Character creation\n-----------------------------------\n\nm:addOverride('xi.player.charCreate', function(player)\n    local declared = declare(player, gilSource.SCRIPT, 'starting_gil')\n\n    local result = super(player)\n    retire(declared)\n\n    return result\nend)\n\n-----------------------------------\n-- Mob drops and Mug\n--\n-- Both are gil created from a mob's purse, so both share the AUDIT_GIL_MOBS gate.\n-----------------------------------\n\n-- Fires for every alliance member before the core hands out the drop. Only the killer declares;\n-- the C++ side widens the reason to the alliance in zone, and the zone tick retires it afterwards.\nm:addOverride('xi.mob.onMobDeathEx', function(mob, player, isKiller, isWeaponSkillKill)\n    if isKiller then\n        declare(player, gilSource.MOB_DROP, 'mob_drop', mob and mob:getID() or 0)\n    end\n\n    return super(mob, player, isKiller, isWeaponSkillKill)\nend)\n\nm:addOverride('xi.job_utils.thief.useMug', function(player, target, ability, action)\n    local declared = declare(player, gilSource.MOB_DROP, 'mug', target and target:getID() or 0)\n\n    local result = super(player, target, ability, action)\n    retire(declared)\n\n    return result\nend)\n\n-----------------------------------\n-- Chocobo rental\n-----------------------------------\n\nm:addOverride('xi.rentalChocobo.renterOnEventFinish', function(player, csid, option, eventSucceed)\n    local declared = declare(player, gilSource.SCRIPT, 'chocobo_rental')\n\n    local result = super(player, csid, option, eventSucceed)\n    retire(declared)\n\n    return result\nend)\n\n-----------------------------------\n-- Field/Grounds of Valor regime rewards\n-----------------------------------\n\nm:addOverride('xi.regime.checkRegime', function(player, mob, regimeId, index, regimeType)\n    local declared = declare(player, gilSource.SCRIPT, 'regime_reward')\n\n    local result = super(player, mob, regimeId, index, regimeType)\n    retire(declared)\n\n    return result\nend)\n\n-----------------------------------\n-- GM gil commands\n--\n-- !givegil and !takegil move the target's gil, so the target is the actor and the GM the counterparty.\n-----------------------------------\n\nlocal function resolveGilCommandTarget(player, target)\n    if not target then\n        return player\n    end\n\n    return GetPlayerByName(target)\nend\n\nm:addOverride('xi.commands.givegil.onTrigger', function(player, amount, target)\n    local declared = declare(resolveGilCommandTarget(player, target), gilSource.GM_COMMAND, 'givegil', player:getID())\n\n    local result = super(player, amount, target)\n    retire(declared)\n\n    return result\nend)\n\nm:addOverride('xi.commands.takegil.onTrigger', function(player, amount, target)\n    local declared = declare(resolveGilCommandTarget(player, target), gilSource.GM_COMMAND, 'takegil', player:getID())\n\n    local result = super(player, amount, target)\n    retire(declared)\n\n    return result\nend)\n\nm:addOverride('xi.commands.setgil.onTrigger', function(player, amount)\n    local declared = declare(player, gilSource.GM_COMMAND, 'setgil')\n\n    local result = super(player, amount)\n    retire(declared)\n\n    return result\nend)\n\nreturn m\n"},["scripts/actions/abilities/accession.lua"]={["Path"]="scripts/actions/abilities/accession.lua",["SHA256"]="82c36e4fd4d96c9fefe1b43ca41aece2496bc02463903252fb2992e4a95fab8c",["Text"]="-----------------------------------\n-- Ability: Accession\n-- Extends the effect of your next healing or enhancing white magic spell to party members within range.\n-- MP cost and casting time are doubled.\n-- Obtained: Scholar Level 40\n-- Recast Time: Stratagem Charge\n-- Duration: 1 compatible white magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.ACCESSION) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ACCESSION, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.ACCESSION\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/accomplice.lua"]={["Path"]="scripts/actions/abilities/accomplice.lua",["SHA256"]="03f2ca758de2f68104305a5e165bf664b05e0fcb026cd939fd9e6452b7e2d6da",["Text"]="-----------------------------------\n-- Ability: Accomplice\n-- Steals half of the target party member's enmity and redirects it to the thief.\n-- Obtained: Thief Level 65\n-- Recast Time: 5:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.thief.checkAccomplice(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.thief.useAccomplice(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/activate.lua"]={["Path"]="scripts/actions/abilities/activate.lua",["SHA256"]="56dea2ba6d7f33c94404e99d6a98116133b0b8876e90d96a3f75c9511015dc97",["Text"]="-----------------------------------\n-- Ability: Activate\n-- Calls forth your automaton.\n-- Obtained: Puppetmaster Level 1\n-- Recast Time: 0:20:00 (0:16:40 with full merits)\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityCheckActivate(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.puppetmaster.onAbilityUseActivate(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/addendum_black.lua"]={["Path"]="scripts/actions/abilities/addendum_black.lua",["SHA256"]="7075567d2a7f1c6f5f434726d7731ebb07d7dbcff281ae9f950d263502c7e083",["Text"]="-----------------------------------\n-- Ability: Addendum: Black\n-- Allows access to additional Black Magic spells while using Dark Arts.\n-- Obtained: Scholar Level 30\n-- Recast Time: Stratagem Charge\n-- Duration: 2 hours\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.ADDENDUM_BLACK) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:delStatusEffectSilent(xi.effect.LIGHT_ARTS)\n    player:delStatusEffectSilent(xi.effect.ADDENDUM_WHITE)\n    player:delStatusEffectSilent(xi.effect.DARK_ARTS)\n\n    local effectbonus = player:getMod(xi.mod.DARK_ARTS_EFFECT)\n    local helixbonus  = 0\n\n    if player:getMainJob() == xi.job.SCH and player:getMainLvl() >= 20 then\n        helixbonus = math.floor(player:getMainLvl() / 4)\n    end\n\n    player:addStatusEffect(xi.effect.ADDENDUM_BLACK, { power = effectbonus, duration = 7200, origin = player, subPower = helixbonus, silent = true })\n\n    return xi.effect.ADDENDUM_BLACK\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/addendum_white.lua"]={["Path"]="scripts/actions/abilities/addendum_white.lua",["SHA256"]="c5af93f46fd35b9ce06c1763b8fead330c78f83fa9c9a50cb6b748380d54164a",["Text"]="-----------------------------------\n-- Ability: Addendum: White\n-- Allows access to additional White Magic spells while using Light Arts.\n-- Obtained: Scholar Level 10\n-- Recast Time: Stratagem Charge\n-- Duration: 2 hours\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.ADDENDUM_WHITE) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:delStatusEffectSilent(xi.effect.DARK_ARTS)\n    player:delStatusEffectSilent(xi.effect.ADDENDUM_BLACK)\n    player:delStatusEffectSilent(xi.effect.LIGHT_ARTS)\n\n    local effectbonus = player:getMod(xi.mod.LIGHT_ARTS_EFFECT)\n    local regenbonus  = 0\n\n    if player:getMainJob() == xi.job.SCH and player:getMainLvl() >= 20 then\n        regenbonus = 3 * math.floor((player:getMainLvl() - 10) / 10)\n    end\n\n    player:addStatusEffect(xi.effect.ADDENDUM_WHITE, { power = effectbonus, duration = 7200, origin = player, subPower = regenbonus, silent = true })\n\n    return xi.effect.ADDENDUM_WHITE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/afflatus_misery.lua"]={["Path"]="scripts/actions/abilities/afflatus_misery.lua",["SHA256"]="df8948d7b6d94b0192fb4f4b88f80cbc9d900528308738ec473cbe62bef9abce",["Text"]="-----------------------------------\n-- Ability: Afflatus Misery\n-- Inspires you to draw strength from the damage you take.\n-- Obtained: White Mage Level 40\n-- Recast Time: 1:00\n-- Duration: 2 hours\n-- Restriction: WHM main only\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.white_mage.useAfflatusMisery(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/afflatus_solace.lua"]={["Path"]="scripts/actions/abilities/afflatus_solace.lua",["SHA256"]="4f9cf6fa9e7ec1357ff11e317fd3e664fabb023f5123c09114cd54a4f38144c3",["Text"]="-----------------------------------\n-- Ability: Afflatus Solace\n-- Inspires you to draw strength from the healing spells you cast.\n-- Obtained: White Mage Level 40\n-- Recast Time: 1:00\n-- Duration: 2 hours\n-- Restriction: WHM main only\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.white_mage.useAfflatusSolace(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/aggressor.lua"]={["Path"]="scripts/actions/abilities/aggressor.lua",["SHA256"]="08c6cb91e1e0da7be3996d1a80c12fc93ab0c9ab5c79376da7840dc850dfac1f",["Text"]="-----------------------------------\n-- Ability: Aggressor\n-- Job: Warrior\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.warrior.useAggressor(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/alacrity.lua"]={["Path"]="scripts/actions/abilities/alacrity.lua",["SHA256"]="96abcbe0704f325bf297a237f40a7096e5671700f73334a1702afa1a7d42a22f",["Text"]="-----------------------------------\n-- Ability: Alacrity\n-- Reduces the casting and the recast time of your next black magic spell by 50%.\n-- Obtained: Scholar Level 25\n-- Recast Time: Stratagem Charge\n-- Duration: 1 black magic spell or 60 seconds, whichever occurs first.\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.ALACRITY) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ALACRITY, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.ALACRITY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/allies_roll.lua"]={["Path"]="scripts/actions/abilities/allies_roll.lua",["SHA256"]="af63cdc00bcdaa9bdb54de9e32ab294e70055804387d10c61b4a716d208ca30c",["Text"]="-----------------------------------\n-- Ability: Allies's Roll\n-- Enhances skillchain damage and skillchain accuracy for party members within area of effect.\n-- Optimal Job: None\n-- Lucky Number: 3\n-- Unlucky Number: 10\n-- Level: 89\n-- Phantom Roll +1 Value: 1\n--\n-- Die Roll    | Skillchain Bonus\n-- --------    -------\n-- 1           |+2\n-- 2           |+3\n-- 3           |+20\n-- 4           |+5\n-- 5           |+7\n-- 6           |+9\n-- 7           |+11\n-- 8           |+13\n-- 9           |+15\n-- 10          |+1\n-- 11          |+25\n-- Bust        |-5\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/altruism.lua"]={["Path"]="scripts/actions/abilities/altruism.lua",["SHA256"]="d51cb56896e66c5f54cdaa42b8512fbcfaced307869225d93379ccd92f8789de",["Text"]="-----------------------------------\n-- Ability: Altruism\n-- Increases the accuracy of your next White Magic spell.\n-- Obtained: Scholar Level 75 Tier 2 Merit Points\n-- Recast Time: Stratagem Charge\n-- Duration: 1 white magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.ALTRUISM) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ALTRUISM, { power = player:getMerit(xi.merit.ALTRUISM), duration = 60, origin = player })\n\n    return xi.effect.ALTRUISM\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ancient_circle.lua"]={["Path"]="scripts/actions/abilities/ancient_circle.lua",["SHA256"]="f04e9806c34e7a991701ab2af2eb637a0cf1a5f5440ee96c4641b32fcecc694c",["Text"]="-----------------------------------\n-- Ability: Ancient Circle\n-- Grants resistance, defense, and attack against dragons to party members within the area of effect.\n-- Obtained: Dragoon Level 5\n-- Recast Time: 5:00\n-- Duration: 03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dragoon.useAncientCircle(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/angon.lua"]={["Path"]="scripts/actions/abilities/angon.lua",["SHA256"]="c843375dbc9612e7df2857bd20ca6a4f3597481a67bb933e4d0c75fa516a7540",["Text"]="-----------------------------------\n-- Ability: Angon\n-- Expends an Angon to lower an enemy's defense.\n-- Obtained: Dragoon Level 75\n-- Recast Time: 0:03:00\n-- Duration: 0:00:30 (+0:00:15 for each merit, cap is 0:01:30)\n-- Effect: Physical defense of target approximately -20% (51/256).\n-- Range: 10.0 yalms\n-- Notes: Only fails if it can't apply the def down status.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dragoon.abilityCheckAngon(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.dragoon.useAngon(player, target, ability)\nend\n\nreturn abilityObject\n"}};
